// Scenario data: cg  (CG_NODES)
// Split out of scenario-generator.html on 2026-08-01.
// Edit THIS file to change this scenario — the main file no longer holds node data.
window.SCEN_NODES = window.SCEN_NODES || {};
(function(){
const CG_NODES = {};

// ---- ARC 1: THE POWER OF GEASS ----

CG_NODES['cg_start'] = {text:`Area 11. That is what they call Japan now.\n\nSeven years ago, the Holy Britannian Empire — the world's greatest superpower — invaded Japan using giant humanoid war machines called Knightmare Frames. The war lasted one month. Japan fell. Its people were stripped of their name, their rights, their dignity. They are "Elevens" now.\n\nYou are a Britannian student living in the Tokyo Settlement — the gleaming colonial city built on top of occupied Japan. But you are not what you seem. You harbor a secret hatred for the Empire, and you have connections to the Japanese resistance.\n\nToday, everything changes.\n\nA terrorist truck crashes near your school. Inside: a capsule the military is desperate to recover. You stumble into the wreckage and find not a weapon, but a girl — green-haired, golden-eyed, chained like a prisoner.\n\nBritannian soldiers find you. They raise their guns. This is it — you are going to die in an alley for being in the wrong place.\n\nThe girl grabs your hand.\n\n"Do you want power?" she whispers. "The power to change this world?"\n\nSomething erupts in your mind. A red sigil blazes in your left eye. And suddenly, you KNOW — you can command anyone. Once. Absolutely. Irresistibly.\n\nThe soldier raises his rifle. Your eye burns.\n\n"Die," you say. And he does.`,scene:'awakening',mood:'#cc0000',characters:['CC'],choices:[{text:'Use the Geass to escape and plan your next move carefully.',next:'cg_escape_plan',effects:{stats:{int:1,per:1}}},{text:'Use the Geass to turn the soldiers against each other — test the limits immediately.',next:'cg_test_geass',effects:{stats:{cou:1,str:1}}},{text:'Find the girl who gave you this power — she has answers.',next:'cg_find_cc',effects:{stats:{cha:1},relationships:{cc:2}}}]};

CG_NODES['cg_escape_plan'] = {text:`You command the remaining soldiers to forget they saw you and walk away. They comply without hesitation — eyes glazed, bodies moving on autopilot.\n\nGeass. Absolute obedience. One command per person. Once used, the target obeys without question and remembers nothing.\n\nThe implications hit you like a freight train. With this power, you could:\n- Infiltrate Britannian military command\n- Build an army from nothing\n- Destroy the Empire from within\n\nBut first, you need to understand the rules. The green-haired girl — C.C. — finds you that evening.\n\n"The Geass responds to your deepest desire," she says, eating pizza on your couch like she owns the place. "Yours is the Power of Absolute Obedience. Use it wisely — every person can only be commanded once. And the power will grow stronger over time. Possibly beyond your control."\n\n"What do you want in return?"\n\nShe smiles. "That is a conversation for later. For now — what will you do with the power of a king?"`,scene:'planning',mood:'#636e72',characters:['CC'],effects:{relationships:{cc:1}},choices:[{text:'Contact the Japanese resistance — they need a leader with an edge.',next:'cg_contact_resistance',effects:{stats:{cha:1}}},{text:'Create a masked identity — lead the rebellion without exposing yourself.',next:'cg_create_zero',effects:{stats:{int:2}}},{text:'Return to Ashford Academy — maintain your cover and protect Nunnally.',next:'cg_ashford_life',effects:{stats:{cha:1}}}]};

CG_NODES['cg_test_geass'] = {text:`You command one soldier to shoot the others. He does — mechanical, emotionless, efficient. Three soldiers fall. The fourth turns and you command him to kneel. He drops.\n\nThe power is absolute. No resistance. No negotiation. You speak, they obey.\n\nIt is intoxicating. And terrifying.\n\nC.C. appears behind you, unfazed by the carnage. "You learn quickly. Most Geass users take days to accept what they can do. You took seconds."\n\n"I have been waiting for something like this my entire life," you reply. "Britannia took everything from me. Now I have the means to take it back."\n\n"The means, yes. The method?" She tilts her head. "That is the question that will define you."\n\nShe is right. Raw power means nothing without a plan. And to fight an empire, you need more than a magic eye — you need an army.`,scene:'awakening',mood:'#cc0000',characters:['CC'],effects:{stats:{cou:1},relationships:{cc:1}},choices:[{text:'Build an identity — become a symbol the resistance can rally behind.',next:'cg_create_zero',effects:{stats:{int:1}}},{text:'Go directly to the resistance fighters — prove your worth in battle.',next:'cg_contact_resistance',effects:{stats:{str:1}}}]};

CG_NODES['cg_find_cc'] = {text:`The green-haired girl sits on a rooftop, watching the military chaos below. She seems entirely unbothered by the fact that soldiers are hunting her.\n\n"You gave me this power," you say. "Why?"\n\n"Because you asked for it. I merely granted what was already inside you — the desire to command, to change, to destroy and rebuild." She looks at you with ancient eyes. "I am C.C. I have existed for a very long time. The Geass is a contract between us — I give you power, and in return, you will fulfill my wish."\n\n"What wish?"\n\n"When you are ready to hear it." She bites into a slice of pizza she pulled from nowhere. "For now, focus on what YOU want. You hate Britannia. You want to destroy it. The Geass gives you the tool. But a tool without a craftsman is just metal."\n\nShe is enigmatic, maddening, and apparently immortal — you watched a soldier shoot her in the head earlier. She got back up.\n\n"So," C.C. says. "What is your plan, contractor?"`,scene:'revelation',mood:'#636e72',characters:['CC'],effects:{relationships:{cc:2}},choices:[{text:'Build a revolution — but first, create an identity that cannot be traced back to you.',next:'cg_create_zero',effects:{stats:{int:1}}},{text:'Find Kallen and the Shinjuku resistance cell — they are already fighting.',next:'cg_contact_resistance',effects:{stats:{cou:1}}},{text:'C.C. freezes — she senses something. A previous contractor is close.',next:'cg_mao_appears',effects:{stats:{per:1},relationships:{cc:1}}}]};

CG_NODES['cg_create_zero'] = {text:`A revolution needs a face. But YOUR face is too dangerous — you are a Britannian student with connections that would unravel everything if exposed.\n\nSo you create a mask. Literally.\n\nA sweeping purple cape. A black bodysuit. And a helmet — angular, dramatic, with a mirrored visor that hides your identity completely. You look like a villain from a stage play.\n\nPerfect.\n\n"I am Zero," you announce to the resistance cell you have contacted. "I am neither Britannian nor Japanese. I am the enemy of injustice itself."\n\nThey are skeptical. A masked stranger asking them to follow? But you prove yourself — using Geass to extract military intelligence, predicting Britannian troop movements, orchestrating a rescue of captured resistance fighters that goes off without a single casualty.\n\nKallen Kozuki — half-Britannian, half-Japanese, full rebel — watches you with suspicion and hope. She is the best Knightmare pilot the resistance has, and she does not trust easily.\n\n"You are either a genius or a lunatic," she says.\n\n"Possibly both," you reply. It is not a joke.`,scene:'planning',mood:'#2a0845',characters:['Kallen'],effects:{stats:{int:1},flags:{zero_identity:true},relationships:{kallen:2}},choices:[{text:'Organize the resistance into a proper military force — the Black Knights.',next:'cg_black_knights',effects:{stats:{cha:2}}},{text:'Plan a dramatic public debut — Zero must become a legend.',next:'cg_zero_debut',effects:{stats:{int:1,cha:1}}},{text:'The SAZ massacre changed everything. Euphemia\'s dream of peace, destroyed by a Geass gone wrong.',next:'cg_euphemia_massacre',effects:{stats:{int:1}}}]};

CG_NODES['cg_contact_resistance'] = {text:`The Shinjuku resistance cell operates from the ruins of old Tokyo — the ghetto where Japanese "Elevens" are forced to live. Crumbling buildings, rationed food, and the constant threat of Britannian raids.\n\nTheir leader, Ohgi, is a former schoolteacher who picked up a gun because no one else would. He is kind, earnest, and completely out of his depth.\n\nKallen Kozuki is the fighter — half-Britannian, half-Japanese, she pilots a stolen Glasgow Knightmare Frame and fights with a fury born from watching her people crushed.\n\nThey are brave. They are also losing. Badly.\n\n"We need more than courage," Ohgi admits. "We need strategy. Weapons. Someone who can outthink the Britannian military."\n\nYou have Geass. You have a mind for strategy. And you have something they desperately lack: a plan.\n\nBut first, they need to trust you. A Britannian walking into a resistance cell does not inspire confidence.`,scene:'daily',mood:'#636e72',characters:['Ohgi','Kallen'],effects:{relationships:{ohgi:1,kallen:1}},choices:[{text:'Prove yourself in battle — lead them to a victory they could not achieve alone.',next:'cg_zero_debut',effects:{stats:{cou:1,int:1}}},{text:'Create the Zero identity — give them a symbol to follow.',next:'cg_create_zero',effects:{stats:{int:1}}}]};

// ---- ARC 2: THE BLACK KNIGHTS RISE ----

CG_NODES['cg_zero_debut'] = {text:`The debut is theatrical. Deliberate. You hijack a public execution broadcast.\n\nPrince Clovis — the Viceroy of Area 11, a Britannian royal — has ordered the execution of captured resistance fighters on live television. Millions watch.\n\nYou arrive in a stolen transport, cape billowing, mask gleaming. Your voice — digitally altered — fills every screen in the settlement.\n\n"I am Zero. I am here for justice."\n\nUsing Geass on the guards, you free the prisoners on live TV. The military scrambles, but you have anticipated every response — your chess-like mind three moves ahead.\n\nThe escape is flawless. The prisoners are freed. And Zero becomes the most wanted man in Area 11.\n\nThat night, resistance cells across Japan hear the name. Hope — a dangerous, explosive thing — ignites.\n\nKallen finds you after. "That was insane. That was brilliant." She pauses. "Who ARE you?"\n\n"I am Zero. That is all that matters."`,scene:'confrontation',mood:'#d4a017',characters:['Kallen','Clovis'],effects:{stats:{cha:1},relationships:{kallen:2}},choices:[{text:'Form the Black Knights — a military organization to replace scattered resistance cells.',next:'cg_black_knights',effects:{stats:{cha:1,int:1}}},{text:'Confront Prince Clovis directly — use Geass to extract information about Britannia\'s plans.',next:'cg_clovis_confrontation',effects:{stats:{cou:2}}}]};

CG_NODES['cg_clovis_confrontation'] = {text:`You infiltrate the Viceroy's palace. Geass opens every door — guards step aside, security systems are disabled by the people who built them.\n\nPrince Clovis sits on his throne, surrounded by empty wine glasses and the pretense of royalty. He is terrified when you walk in.\n\n"Who are you?! Guards!"\n\n"Your guards cannot hear you," you say. "I am Zero. And I have questions."\n\nYou activate Geass. Clovis's eyes go blank.\n\n"Tell me everything about Code R — the project that created C.C.'s capsule."\n\nHe talks. The project involves human experimentation. Geass users. Something called the Thought Elevator. And behind it all — the Emperor of Britannia, Charles zi Britannia, your father.\n\nYes. Your father. The man who conquered nations and discarded his own children like broken toys.\n\nYou have what you need. Clovis blinks, released from Geass.\n\n"Please," he whimpers. "We are family—"\n\nYou raise the gun. The choice is yours.`,scene:'confrontation',mood:'#cc0000',characters:['Clovis'],effects:{stats:{int:1},flags:{code_r_known:true}},choices:[{text:'Pull the trigger — Clovis is complicit in the occupation and the experiments.',next:'cg_clovis_killed',effects:{stats:{cou:1},flags:{clovis_killed:true}}},{text:'Spare him — use him as an asset, a puppet viceroy under your control.',next:'cg_clovis_spared',effects:{stats:{int:1,cha:1}}}]};

CG_NODES['cg_clovis_killed'] = {text:`The shot echoes through the empty throne room. Prince Clovis la Britannia, Third Prince of the Empire, is dead.\n\nThe news shakes Area 11. A Britannian prince, assassinated by Zero. The settlement panics. The Japanese ghettos erupt in cautious celebration.\n\nBritannia responds by sending a replacement: Princess Cornelia li Britannia — a military genius and one of the Empire's most dangerous commanders. Unlike Clovis, Cornelia does not play at war. She IS war.\n\nWith her comes her knight, Guilford, and her sister, Princess Euphemia — kind, idealistic, and dangerously naive.\n\nThe stakes just rose dramatically. Cornelia will hunt you with a precision Clovis never possessed.\n\nBut you have the Black Knights now. Time to build your army.`,scene:'aftermath',mood:'#cc0000',characters:['Cornelia'],effects:{flags:{cornelia_arrives:true}},choices:[{text:'Form the Black Knights — you need an army to face Cornelia.',next:'cg_black_knights',effects:{stats:{cha:1}}}]};

CG_NODES['cg_clovis_spared'] = {text:`You lower the gun. "You will continue as Viceroy. But you will feed me information — troop movements, security codes, political intelligence. If you betray me, the truth about Code R goes public. Every experiment. Every death. Your name attached to all of it."\n\nClovis nods frantically. A puppet prince on a puppet throne.\n\nFor three weeks, it works. Clovis feeds you intel. You use it to ambush Britannian patrols and rescue Japanese civilians. The Black Knights grow.\n\nThen Clovis cracks. He contacts the homeland and confesses everything. Britannian intelligence extracts him before you can respond.\n\nHis replacement: Princess Cornelia li Britannia. A real commander. A real threat.\n\nYou lost your inside man, but you gained time and intelligence that will prove invaluable. The game continues.`,scene:'aftermath',mood:'#636e72',characters:['Cornelia'],effects:{flags:{cornelia_arrives:true}},choices:[{text:'Build the Black Knights into a force that can challenge Cornelia.',next:'cg_black_knights',effects:{stats:{int:1}}}]};

CG_NODES['cg_black_knights'] = {text:`The Black Knights. Japan's last hope.\n\nYou organize the scattered resistance cells into a unified military force. Zero is the face. You are the brain. And the ideology is simple: "We protect the weak from the strong. We do not serve any nation — we serve justice."\n\nThe core members:\n- Kallen Kozuki: ace pilot, commands the Guren — a next-generation Knightmare Frame with a devastating radiant wave surger\n- Ohgi: deputy commander, the moral compass you sometimes ignore\n- Diethard: a Britannian journalist who defected because he believes Zero will make history\n- Tohdoh: a legendary Japanese military commander who joins after you break him out of prison\n- C.C.: your immortal accomplice who sits in the background eating pizza and knowing more than she says\n\nThe Black Knights win battle after battle. Your strategy is flawless — you use Geass sparingly, relying instead on tactical genius. Each victory recruits more soldiers. Each broadcast from Zero inspires more resistance.\n\nBut Cornelia is adapting. She is not falling for the same tricks twice. And a new player has entered the field: Suzaku Kururugi.`,scene:'daily',mood:'#2a0845',characters:['Kallen','Ohgi','CC','Tohdoh'],effects:{stats:{cha:1},relationships:{kallen:2,ohgi:1}},choices:[{text:'Develop a strategy to defeat Cornelia — she is the key to controlling Area 11.',next:'cg_cornelia_battle',effects:{stats:{int:2}}},{text:'Deal with Suzaku first — he is becoming a problem.',next:'cg_suzaku_conflict',effects:{stats:{per:1}}},{text:'Expand the Black Knights internationally — other conquered nations need liberation too.',next:'cg_expand',effects:{stats:{cha:1,int:1}}},{text:'Reports come in of a disgraced Britannian knight hunting Zero — Jeremiah Gottwald, the Orange Boy.',next:'cg_jeremiah_orange',effects:{stats:{per:1}}}]};

// ---- ARC 3: THE COST OF POWER ----

CG_NODES['cg_cornelia_battle'] = {text:`Cornelia sets a trap at Narita — fortifying a mountain position to bait the Black Knights into a frontal assault. She has studied your tactics and prepared for every move.\n\nExcept one.\n\nYou trigger a landslide. Not with weapons — with geological knowledge and precisely placed charges. The mountain itself becomes your weapon, burying the Britannian base camp.\n\nIn the chaos, the Black Knights strike. Kallen's Guren tears through Cornelia's guard. Tohdoh's custom Knightmare flanks the retreat.\n\nCornelia fights personally — her Gloucester Knightmare is devastating. But you predicted her escape route and positioned forces to cut her off.\n\nFor the first time, a Britannian princess tastes defeat.\n\nBut victory comes with a cost. Civilian casualties from the landslide. Japanese villages in the path of the destruction you unleashed.\n\nOhgi is troubled. "We killed innocents, Zero. Our OWN people."\n\n"Acceptable losses," you reply. And you mean it. And that terrifies you.`,scene:'battle',mood:'#cc0000',characters:['Cornelia','Kallen','Ohgi'],effects:{stats:{int:1},relationships:{ohgi:-1}},choices:[{text:'Press the advantage — pursue Cornelia and finish the job.',next:'cg_euphemia',effects:{stats:{cou:1}}},{text:'Consolidate — rebuild trust with the people you are supposed to protect.',next:'cg_euphemia',effects:{stats:{cha:1},relationships:{ohgi:1}}},{text:'The Geass pulses uncontrollably — you need to deal with this before it destroys everything.',next:'cg_geass_control',effects:{stats:{per:1}}}]};

CG_NODES['cg_suzaku_conflict'] = {text:`Suzaku Kururugi. An Honorary Britannian — a Japanese man who serves the Empire that conquered his country. He pilots the Lancelot, a prototype Knightmare Frame that is faster and more powerful than anything in your arsenal.\n\nHe is also your childhood friend. Before the invasion, before the occupation, you and Suzaku played together in the Kururugi shrine. Two boys who dreamed of changing the world.\n\nNow you are on opposite sides.\n\nSuzaku believes in changing the system from within — rising through Britannian ranks until he has the power to reform the Empire. Peaceful change. Legitimate authority.\n\nYou believe the system cannot be reformed. It must be destroyed.\n\n"You are wrong, Zero," Suzaku declares during a battle. "Violence only creates more violence. I will prove that the right person in the right position can change everything without a single death."\n\n"And how many Japanese died while you climbed that ladder?" you reply.\n\nThe Lancelot and the Black Knights clash. Suzaku's skill is extraordinary — he fights with a death wish's abandon, throwing himself into danger because he secretly does not value his own life.\n\nYou cannot kill him. He was your friend. But you cannot let him stop the rebellion either.`,scene:'confrontation',mood:'#636e72',characters:['Suzaku'],effects:{relationships:{suzaku:1}},choices:[{text:'Try to recruit Suzaku — show him the Empire cannot be changed from within.',next:'cg_euphemia',effects:{stats:{cha:1},relationships:{suzaku:2}}},{text:'Defeat Suzaku in battle — remove him from the board.',next:'cg_euphemia',effects:{stats:{str:1,cou:1}}},{text:'Reveal your identity to Suzaku — take the ultimate risk to forge a real alliance.',next:'cg_suzaku_alliance',check:{stat:'cha',dc:12,pass:'cg_suzaku_alliance',fail:'cg_euphemia'},effects:{stats:{cou:2}}}]};

CG_NODES['cg_expand'] = {text:`The Black Knights reach out to resistance movements worldwide. The EU — a crumbling federation resisting Britannian expansion. The Chinese Federation — an ancient empire controlled by corrupt eunuchs. India. The Middle East. Africa.\n\nBritannia has conquered one-third of the world. The rest lives in fear.\n\nYou send envoys. Share intelligence. Build a network of rebellion that spans continents. If Britannia faces uprisings on every front simultaneously, even their military cannot respond.\n\nThe strategy works — Britannian forces are stretched thin. Reinforcements meant for Area 11 are diverted to quell revolts elsewhere.\n\nBut international politics brings complications. Allies with their own agendas. Leaders who want Zero's power for themselves. The Chinese Federation offers support in exchange for influence over a liberated Japan.\n\n"We are not trading one empire for another," Kallen says firmly.\n\n"Sometimes you must accept imperfect allies to defeat a perfect enemy," you reply.\n\nThe moral lines blur. They always do.`,scene:'planning',mood:'#636e72',characters:['Kallen'],effects:{stats:{int:1},relationships:{kallen:1}},choices:[{text:'Focus on the immediate battle — Area 11 must be liberated first.',next:'cg_euphemia',effects:{stats:{cou:1}}}]};

CG_NODES['cg_euphemia'] = {text:`Princess Euphemia li Britannia — Cornelia's younger sister — proposes the unthinkable: a Special Administrative Zone. A region where Japanese people regain their rights, their names, their dignity. No war. No rebellion. Just... peace.\n\nShe is sincere. You can see it in her eyes — no manipulation, no trap. She genuinely wants to end the suffering.\n\nThe Special Zone would undermine everything you have built. If the Japanese get their rights through Britannia's generosity, they will not need Zero. They will not need the Black Knights. The rebellion dies — not from defeat, but from irrelevance.\n\n"She is dismantling your revolution with kindness," C.C. observes.\n\nYou meet Euphemia privately. She recognizes you — your real identity. Childhood friends.\n\n"Please," she says. "Let me try. If it works, no one else has to die."\n\nYour Geass has been growing stronger. Harder to control. It pulses behind your eye, wanting to activate.\n\nYou argue with her. Make a dark joke: "I could just order you to kill all the Japanese—"\n\nThe Geass activates. Involuntarily. Your worst nightmare.\n\nEuphemia's eyes go blank. "Yes... kill all the Japanese..."\n\n"NO! I did not mean—"\n\nBut Geass is absolute. And Euphemia — sweet, kind Euphemia — picks up a gun and walks toward the crowd.`,scene:'horror',mood:'#cc0000',characters:['Euphemia','CC'],effects:{flags:{euphemia_geass:true}},choices:[{text:'Stop Euphemia — tackle her, restrain her, anything to prevent the massacre.',next:'cg_stop_euphemia',effects:{stats:{cou:2},relationships:{suzaku:-2}}},{text:'Use the tragedy — frame it as Britannia\'s true nature and rally Japan.',next:'cg_use_tragedy',effects:{stats:{int:1},relationships:{suzaku:-3}}},{text:'Fight the Geass — clamp your hand over your eye and stop the command before it takes hold.',next:'cg_euphemia_saved',check:{stat:'per',dc:14,pass:'cg_euphemia_saved',fail:'cg_stop_euphemia'},effects:{stats:{per:2,cou:1}}}]};

CG_NODES['cg_stop_euphemia'] = {text:`You lunge for Euphemia but she is already firing. The Geass command is absolute — she moves with the single-minded purpose of a puppet.\n\nSoldiers follow her orders, confused but obedient. Shots ring out. Japanese civilians fall.\n\nYou tackle Euphemia to the ground. The gun skids away. But the damage is done — dozens dead, hundreds wounded, and the Special Administrative Zone is in flames.\n\nSuzaku arrives. He sees Euphemia on the ground, sees the dead civilians, sees YOU holding the princess.\n\n"What did you do?!" he screams.\n\nYou cannot explain. Telling him the truth — that your magic eye accidentally mind-controlled his beloved Euphemia into committing genocide — is unbelievable. And admitting it means admitting the Geass exists.\n\nEuphemia dies in Suzaku's arms. The Geass burns her mind out. Her last words, free of the command: "Suzaku... did I... do something... good?"\n\nSuzaku's scream echoes across the ruins. He will never forgive you. The personal cost of the Geass is now measured in bodies.`,scene:'horror',mood:'#cc0000',characters:['Euphemia','Suzaku'],effects:{relationships:{suzaku:-3},flags:{euphemia_dead:true}},choices:[{text:'Rally the Black Knights — use the chaos to launch a full rebellion.',next:'cg_rebellion',effects:{stats:{cou:1,int:1}}}]};

CG_NODES['cg_use_tragedy'] = {text:`The monster in you makes a calculation. Euphemia's massacre — caused by YOUR accidental Geass — can be the spark that ignites revolution.\n\nYou broadcast to all of Japan: "Britannia has shown its true face! The Special Zone was a trap! Princess Euphemia ordered the massacre of Japanese civilians! This is the peace Britannia offers — death disguised as kindness!"\n\nIt is a lie. Euphemia was a victim, not a villain. But the lie works.\n\nJapan ERUPTS. Every ghetto, every resistance cell, every person who dared to hope rises up. The Black Knights surge to the front. Britannian forces are overwhelmed.\n\nYou shoot Euphemia yourself. End the Geass. End her suffering. She dies confused, kind, and innocent.\n\nSuzaku cradles her body and swears to destroy Zero.\n\nC.C. watches you from the shadows. "You used an innocent girl's death to start a war."\n\n"I know."\n\n"Can you live with that?"\n\n"I do not have to live with it. I have to WIN with it."`,scene:'horror',mood:'#cc0000',characters:['Euphemia','CC','Suzaku'],effects:{relationships:{suzaku:-3,cc:1},flags:{euphemia_dead:true}},choices:[{text:'Launch the full rebellion — the Black Rebellion.',next:'cg_rebellion',effects:{stats:{int:1,cou:1}}}]};

// ---- ARC 4: THE BLACK REBELLION AND BEYOND ----

CG_NODES['cg_rebellion'] = {text:`The Black Rebellion. Zero's masterwork.\n\nEvery Black Knight unit mobilizes simultaneously. Knightmare Frames pour out of hidden bases. The Guren leads the charge, Kallen at the controls, a blazing red comet cutting through Britannian lines.\n\nTohdoh commands the ground forces with samurai precision. Ohgi coordinates communications. Diethard broadcasts every moment to the world.\n\nYou command from the rear — moving units like chess pieces. The Tokyo Settlement's defenses crumble. Victory is within reach.\n\nThen Suzaku arrives in the Lancelot. Upgraded. Furious. Fighting with nothing left to lose.\n\nHe tears through your forces. The Lancelot's new weapons — the VARIS rifle, the Blaze Luminous shields — are beyond anything the Black Knights can match.\n\nAnd then — a signal from the Britannian homeland. Something you never expected.\n\nYour sister Nunnally — blind, wheelchair-bound, the person you love most in the world — has been kidnapped. Taken to a location only you can reach. If you leave the battle, the rebellion may fail. If you stay, Nunnally dies.\n\nKayaba's dilemma echoes: who do you save?`,scene:'battle',mood:'#cc0000',characters:['Kallen','Suzaku','Tohdoh'],choices:[{text:'Go to Nunnally — she is the reason you started this rebellion. Without her, none of it matters.',next:'cg_save_nunnally',effects:{stats:{cou:1},relationships:{kallen:-1}}},{text:'Stay and command the battle — the fate of millions outweighs one person, even your sister.',next:'cg_stay_battle',effects:{stats:{int:1,cou:2}}},{text:'Before you can decide, every screen in Tokyo lights up — Schneizel has revealed your identity.',next:'cg_identity_exposed',effects:{stats:{per:1}}}]};

CG_NODES['cg_save_nunnally'] = {text:`You abandon the battlefield. The Black Knights see Zero's command unit retreat and panic spreads. Without your strategic mind coordinating the assault, the offensive falters.\n\nCornelia counterattacks. Suzaku leads the charge. The Black Rebellion — hours from victory — collapses.\n\nYou find Nunnally in a Britannian research facility. She is safe. But the trap was set by someone who knows you — knows Zero's true identity.\n\nSuzaku is waiting.\n\n"I know who you are," he says, pointing a gun at your face. "I know what you did to Euphemia."\n\nThe mask comes off. Two childhood friends, pointing weapons at each other, standing on the ruins of a failed revolution.\n\n"Everything I did was for Nunnally," you say. "For a world where she could be happy."\n\n"And everyone who died? Were they for Nunnally too?"\n\nSuzaku pulls the trigger. The world goes dark.\n\nYou wake up months later. The Emperor — your father — has used his own Geass to rewrite your memories. You do not remember being Zero. You do not remember the rebellion. You are just a student again.\n\nBut memories, like revolutions, refuse to stay buried.`,scene:'aftermath',mood:'#cc0000',characters:['Suzaku','Nunnally'],effects:{relationships:{suzaku:-2},flags:{memory_erased:true}},choices:[{text:'The memories return — and so does Zero.',next:'cg_ending_return',effects:{stats:{int:1,cou:1}}}]};

CG_NODES['cg_stay_battle'] = {text:`You remain. The hardest choice you have ever made — choosing millions over the one person you love.\n\n"All units, press the attack! Take the government bureau!"\n\nThe Black Knights surge forward. Kallen's Guren breaches the inner defenses. Tohdoh's forces encircle the settlement. Victory is minutes away.\n\nSuzaku charges through your lines in the Lancelot. You engage him directly — your command unit against his prototype. The fight is devastating.\n\nIn the end, the Tokyo Settlement falls. The Britannian government of Area 11 surrenders. Japan — Area 11 — is liberated.\n\nBut at what cost?\n\nNunnally is gone. Taken to the homeland. Alive, but beyond your reach. The person you fought for, the reason you became Zero — removed from the board.\n\nAnd C.C. whispers: "This is the Geass. It gives you the power to change the world, but it takes everything else. Was it worth it?"\n\nYou stand on the balcony of the conquered government bureau, mask hiding tears.\n\n"Ask me when the war is over."`,scene:'aftermath',mood:'#636e72',characters:['CC','Kallen'],effects:{relationships:{cc:2,kallen:2}},choices:[{text:'Continue the war — liberate the world, then find Nunnally.',next:'cg_ending_king',effects:{stats:{int:1,cou:2}}},{text:'A message arrives from Nunnally. She knows. She has always known.',next:'cg_nunnally_plea',effects:{stats:{cha:1},relationships:{nunnally:3}}}]};

CG_NODES['cg_ending_return'] = {text:`The memories crack through like light through ice. C.C. finds you. Her touch on your forehead is a key that unlocks everything.\n\nYou remember. Zero. The Black Knights. The rebellion. Euphemia. Nunnally.\n\nThe rage is volcanic.\n\nYou rebuild. Faster this time. The Black Knights were scattered but not destroyed. Kallen kept them alive. Ohgi held the pieces together. They were waiting for Zero to return.\n\nAnd this time, you do not just fight Britannia. You fight the Emperor himself — Charles zi Britannia, who possesses the Geass of Memory. Who wants to use a device called the Ragnarok Connection to merge all human consciousness into one mind. A world without lies — because no one can lie if everyone shares one mind.\n\nYou confront him in the Sword of Akasha — a realm between worlds.\n\n"Lies are what make us human," you tell your father. "The ability to deceive is the ability to choose. To imagine. To hope for things that do not yet exist. A world without lies is a world without freedom."\n\nYou command the collective unconscious itself with Geass: "Do not stop the march of time."\n\nThe Emperor dissolves. His plan dies with him.\n\nBut the world still needs saving. And the final sacrifice is yours to make.\n\nYou ascend the throne. Become the Emperor of Britannia. And in one final, terrible act of love, you make yourself the villain of the entire world — so that when you die, all of humanity's hatred dies with you.\n\nSuzaku, wearing the mask of Zero, drives a sword through your chest on live television.\n\nThe crowd cheers. The tyrant is dead.\n\nNunnally holds your hand as you bleed. "You were always... trying to protect me..."\n\n"I destroyed the world," you whisper, "and created it anew."\n\nZero Requiem is complete. The world is free. And the man who freed it dies as its greatest villain.\n\nThat was always the plan.`,scene:'end',mood:'#cc0000',ending:'Zero Requiem',characters:['CC','Suzaku','Nunnally'],choices:[{text:'But what happened AFTER the Requiem? Continue the story.',next:'cg_ending_requiem_aftermath',effects:{stats:{per:1}}}]};

CG_NODES['cg_ending_king'] = {text:`The war expands. Japan was just the beginning.\n\nThe United Federation of Nations — your creation — rises against Britannia on every front. The EU, the Chinese Federation, Africa, the Middle East. A coalition of the conquered.\n\nYou lead from the front now, mask on, cape billowing, the demon emperor of revolution. The Black Knights are an army. Your Geass is a scalpel that cuts through every defense.\n\nBut you are losing yourself. Every command, every manipulation, every sacrifice chips away at the person you were. You use Geass on allies when they hesitate. You sacrifice pawns — people — without flinching.\n\nKallen confronts you. "When does it end, Zero? When do we stop fighting?"\n\n"When the world is free."\n\n"And what about US? Are WE free? Or are we just pieces on your board too?"\n\nThe question stings because the answer is uncomfortable.\n\nYou take the Britannian throne. Not through Geass — through military conquest. The Empire falls from the top.\n\nBut a throne built on blood requires a final act. You become the world's enemy — a tyrant so terrible that all of humanity unites against you. And then you let Suzaku — wearing the mask of Zero — kill you.\n\nZero lives. You die. The world unites in hatred of a dead emperor and love of a masked hero.\n\nNunnally finds out the truth too late. She weeps over your body.\n\nC.C. carries your memory. "He was not the demon they think he was," she says to no one. "He was a boy who loved his sister. And he burned the world to keep her safe."\n\nThe Geass fades from your eye. The contract is fulfilled. The king is dead.\n\nLong live Zero.`,scene:'end',mood:'#2a0845',ending:'The Demon Emperor\'s Sacrifice',characters:['Kallen','CC','Suzaku','Nunnally'],choices:[{text:'The Code activates. Lelouch opens his eyes. Continue the story.',next:'cg_ending_king_price',effects:{stats:{per:1}}}]};

// ---- ARC 3B: ALTERNATE TIMELINE — THE SUZAKU ALLIANCE ----

CG_NODES['cg_suzaku_alliance'] = {text:`You do the unthinkable. Mid-battle, you open a private channel to the Lancelot.\n\n"Suzaku. It is me."\n\nSilence. Then: "...Lelouch?"\n\nYou remove your mask on camera — just for him, encrypted channel, no witnesses. His Lancelot freezes mid-swing.\n\n"I know what you are thinking," you say. "I lied. I manipulated. I built an army behind a mask while you saluted the flag of the people who murdered our childhood. But I am asking you — not as Zero, not as a prince — as the kid who used to catch frogs with you at the Kururugi shrine. Help me."\n\nSuzaku's breathing is ragged. "You killed people, Lelouch. You started a war."\n\n"Britannia started the war. I am trying to end it. And I cannot do it without you. Not because I need the Lancelot — because I need someone who will stop me when I go too far."\n\nThe longest pause of your life.\n\n"If I find out you used Geass on me — even once — I will kill you myself."\n\n"Deal."\n\nThe Lancelot sheathes its sword. For the first time since the invasion, you and Suzaku Kururugi are on the same side.`,scene:'confrontation',mood:'#2a0845',characters:['Suzaku'],effects:{stats:{cha:1},relationships:{suzaku:3},flags:{suzaku_allied:true}},choices:[{text:'Plan a joint operation — hit the Britannians where they least expect cooperation between Zero and the Lancelot.',next:'cg_joint_operation',effects:{stats:{int:1}}},{text:'Introduce Suzaku to the Black Knights leadership — they need to accept him.',next:'cg_trust_test',effects:{stats:{cha:1}}}]};

CG_NODES['cg_joint_operation'] = {text:`The plan is elegant in its audacity: Suzaku feeds you Britannian patrol routes and security codes from the inside, while the Black Knights strike with surgical precision from the outside. Zero and the White Knight, working in tandem.\n\nThe first target: a Britannian weapons depot supplying Cornelia's forces. Suzaku disables the perimeter from within — "equipment malfunction," he reports to his superiors. The Black Knights pour through the gap.\n\nKallen leads the assault in the Guren. She does not know who tipped you off, and she is suspicious.\n\n"Your intel has been unnervingly perfect lately, Zero. Care to share your source?"\n\n"A friend on the inside."\n\n"Britannians do not have friends on our side."\n\nThe operation goes flawlessly. Twelve Knightmare Frames captured. Enough weapons to arm three resistance cells. Zero casualties.\n\nBut Cornelia is no fool. She notices the pattern — her security keeps failing at exactly the wrong moments. She begins an internal investigation.\n\nSuzaku calls you that night. "They are getting suspicious. Cornelia has ordered loyalty screenings for all Honorary Britannians. I have maybe two weeks before they catch me."\n\n"Then we move faster."`,scene:'planning',mood:'#636e72',characters:['Kallen','Suzaku','Cornelia'],effects:{stats:{int:1},relationships:{kallen:1,suzaku:1}},choices:[{text:'Accelerate the timeline — launch the assault on the Tokyo Settlement before Cornelia closes in.',next:'cg_dual_assault',effects:{stats:{cou:2}}},{text:'Extract Suzaku first — if he is caught, you lose everything and a friend.',next:'cg_trust_test',effects:{stats:{per:1},relationships:{suzaku:2}}}]};

CG_NODES['cg_trust_test'] = {text:`Introducing Suzaku to the Black Knights is like throwing a match into a gas leak.\n\nOhgi stares. Tohdoh's hand goes to his sword. Kallen physically steps between Suzaku and the rest of the room, her hand on her sidearm.\n\n"An Honorary Britannian," Tohdoh says, each word a blade. "The pilot of the Lancelot. The man who has killed more Black Knights than any other single combatant. And you want us to trust him."\n\n"I want you to use him," you reply. "His access to Britannian intelligence is worth more than a battalion."\n\n"I am standing right here," Suzaku says quietly. "And I am not doing this for Zero. I am doing this because Britannia's promises of reform are lies. I climbed their ladder and all I found at the top was more ladders."\n\nKallen locks eyes with him. "You shot down four of our Knightmare Frames at Narita. I watched a friend burn inside his cockpit because of you."\n\n"I know. I remember every one."\n\nThe room is a powder keg. You need to hold this together.`,scene:'confrontation',mood:'#636e72',characters:['Suzaku','Kallen','Ohgi','Tohdoh'],effects:{relationships:{suzaku:-1,ohgi:-1}},choices:[{text:'Appeal to their shared hatred of Britannia — remind them what they are all fighting for.',next:'cg_trust_holds',check:{stat:'cha',dc:13,pass:'cg_trust_holds',fail:'cg_trust_breaks'},effects:{stats:{cha:1}}},{text:'Show them the intelligence Suzaku has already provided — let results speak louder than grudges.',next:'cg_trust_holds',check:{stat:'int',dc:12,pass:'cg_trust_holds',fail:'cg_trust_breaks'},effects:{stats:{int:1}}}]};

CG_NODES['cg_trust_holds'] = {text:`It takes three hours of argument, two near-fistfights, and one moment where Tohdoh actually draws his blade — but you hold it together.\n\nThe turning point comes when Suzaku shares something he did not have to: the location of a Britannian prison camp holding Japanese civilians. Families. Children. Information he could have kept to himself.\n\nOhgi looks at the coordinates. Looks at Suzaku. "My sister... she was taken to a camp like that."\n\n"Then let me help you get her back," Suzaku says.\n\nThe rescue operation is flawless. Sixty-three civilians freed. When they emerge blinking into sunlight, Ohgi's sister among them, something shifts in the Black Knights' collective spine.\n\nSuzaku is not accepted. Not yet. But he is tolerated. And tolerance, in a war, is the first step toward trust.\n\nKallen finds you afterward. "If he betrays us, I am holding you personally responsible."\n\n"He will not."\n\n"You sound sure."\n\n"I knew him when we were ten. He cried when a bird hit a window. That person is still in there."`,scene:'aftermath',mood:'#636e72',characters:['Suzaku','Kallen','Ohgi'],effects:{stats:{cha:1},relationships:{suzaku:2,ohgi:2,kallen:1}},choices:[{text:'Launch the combined assault on the Tokyo Settlement — now, while you have unity.',next:'cg_dual_assault',effects:{stats:{cou:1,int:1}}}]};

CG_NODES['cg_trust_breaks'] = {text:`It falls apart faster than you can react.\n\nTohdoh refuses outright. "I will not serve alongside the pilot who killed my students at Itsukushima. Zero, I followed you because you gave Japan hope. This gives Japan a traitor in its ranks."\n\nOhgi wavers, then sides with Tohdoh. "The rank and file will mutiny if they see the Lancelot pilot in our base. I am sorry, Zero."\n\nKallen says nothing. Her silence is worse than opposition.\n\nSuzaku reads the room and stands. "I will leave. You do not need a civil war inside your own rebellion." He looks at you — and for a moment, he is ten years old again, standing outside a circle of kids who do not want him there. "I thought this time might be different."\n\nHe walks out. The Black Knights watch him go. Nobody stops him.\n\nYou catch him at the exit. "This is not over."\n\n"It is for now." He puts on his Britannian uniform like armor. "Do what you do, Lelouch. Just... try not to get everyone killed."\n\nYou have the Black Knights. You have lost Suzaku — perhaps for good.`,scene:'aftermath',mood:'#636e72',characters:['Suzaku','Tohdoh','Ohgi'],effects:{relationships:{suzaku:-2,ohgi:-1}},choices:[{text:'Press on without Suzaku — the rebellion cannot wait for everyone to agree.',next:'cg_cornelia_battle',effects:{stats:{cou:1}}},{text:'Go after Suzaku privately — maintain the alliance in secret even if the Knights refuse to accept it.',next:'cg_joint_operation',effects:{stats:{int:1},relationships:{suzaku:1}}}]};

CG_NODES['cg_dual_assault'] = {text:`The Tokyo Settlement. The seat of Britannian power in Area 11. Today, it falls.\n\nThe plan is unprecedented: a coordinated inside-outside assault. Suzaku, still wearing his Britannian uniform, disables the Lancelot's IFF transponder and jams Cornelia's communications from within. The Black Knights hit the outer wall simultaneously from four directions.\n\nKallen's Guren rips through the main gate. Tohdoh's strike force flanks the government district. And you — in your command unit — direct every piece on the board with a precision that makes chess look sloppy.\n\nCornelia scrambles to respond, but her orders are not reaching her units. Suzaku has seen to that.\n\n"Cornelia," you broadcast on an open channel. "Your communications are compromised. Your reinforcements are engaged. And your most trusted Knight is no longer yours. Surrender Area 11."\n\n"ZERO!" Cornelia roars. She launches in her Gloucester personally, cutting through Black Knight units with terrifying skill.\n\nSuzaku intercepts her in the Lancelot. Former allies, now enemies. The duel is savage.`,scene:'battle',mood:'#cc0000',characters:['Suzaku','Kallen','Cornelia','Tohdoh'],effects:{stats:{int:1}},choices:[{text:'Support Suzaku against Cornelia — coordinate a pincer with Kallen.',next:'cg_cornelia_duel',effects:{stats:{int:1}}},{text:'Let Suzaku handle Cornelia — push for the government bureau while they are distracted.',next:'cg_ending_alliance',effects:{stats:{cou:1}}}]};

CG_NODES['cg_cornelia_duel'] = {text:`Cornelia li Britannia fights like a woman with nothing left to lose. Her Gloucester parries the Lancelot's VARIS rifle and closes to melee range — she is better up close and she knows it.\n\n"Kururugi!" she shouts, blade crashing against his shield. "You swore an oath to Britannia! To Euphemia!"\n\n"I swore to protect people!" Suzaku fires back. "Euphemia would want PEACE, not this!"\n\nYou direct Kallen to flank from the east. The Guren's radiant wave surger charges — one clean hit and Cornelia's Knightmare is finished.\n\nBut Cornelia is not just skilled. She is brilliant. She reads the flanking maneuver and pivots, using Suzaku's own attack momentum to throw him into Kallen's path. The Guren has to abort its strike to avoid hitting the Lancelot.`,scene:'battle',mood:'#cc0000',characters:['Cornelia','Suzaku','Kallen'],choices:[{text:'Order a risky three-way synchronized attack — all units fire simultaneously.',next:'cg_ending_alliance',check:{stat:'int',dc:14,pass:'cg_ending_alliance',fail:'cg_cornelia_duel_fail'},effects:{stats:{int:1}}},{text:'Use Geass on Cornelia through an open comm channel — command her to stand down.',next:'cg_ending_alliance',check:{stat:'per',dc:11,pass:'cg_ending_alliance',fail:'cg_cornelia_duel_fail'},effects:{stats:{per:1}}}]};

CG_NODES['cg_cornelia_duel_fail'] = {text:`The synchronized attack collapses. Cornelia exploits the gap — her Gloucester drives a lance through Kallen's Guren, disabling the radiant wave surger. Kallen ejects just in time.\n\nSuzaku takes a hit covering Kallen's retreat. The Lancelot's left arm is sheared clean off. He is still fighting, but barely.\n\n"Fall back!" you command. "All units, fall back to secondary positions!"\n\nCornelia does not pursue. She is too damaged herself — the Gloucester is limping, sparking, half its armor gone. But Area 11 is still hers.\n\nThe assault failed. Your grand alliance could not crack Cornelia's iron will.\n\nSuzaku contacts you that night. "We lost today. But Cornelia is weakened. Her forces are depleted. If we regroup, hit her again before reinforcements arrive from the homeland..."\n\nKallen, nursing bruised ribs, adds: "The Guren can be repaired in forty-eight hours. I want a rematch."\n\nYou lost the battle. But the alliance holds. And in war, that counts for something.`,scene:'aftermath',mood:'#636e72',characters:['Suzaku','Kallen','Cornelia'],effects:{stats:{per:1},relationships:{kallen:1,suzaku:1}},choices:[{text:'Regroup and plan a second assault — learn from the failure.',next:'cg_ending_alliance',effects:{stats:{int:2}}}]};

CG_NODES['cg_ending_alliance'] = {text:`The Tokyo Settlement falls. Not in fire and screaming, but in a coordinated capitulation that minimizes casualties on both sides. Suzaku's inside knowledge and your strategic mind create something neither of you could have achieved alone: a clean victory.\n\nCornelia surrenders with dignity. You offer her terms — leave Area 11, take your surviving forces, report to the homeland that Japan is no longer theirs. She accepts, because the alternative is annihilation, and Cornelia loves her soldiers too much to spend their lives on pride.\n\nJapan is liberated. The Black Knights hold the government bureau. And for the first time in seven years, a Japanese flag flies over Tokyo.\n\nBut this is not the ending you once imagined — the lone king sacrificing himself on the board. Suzaku changed that.\n\n"You were going to do something stupid and noble, were you not?" Suzaku asks, standing on the balcony as fireworks light the Tokyo skyline. "Some grand sacrifice where you die and the world magically gets better."\n\n"The thought crossed my mind."\n\n"Idiot." He almost smiles. "You do not get to die. You have to stay and fix what you broke. That is the actual hard part."\n\nC.C. watches from the shadows, pizza in hand. She seems almost disappointed — or maybe relieved. It is hard to tell with immortals.\n\nKallen finds you both. "The Chinese Federation wants to negotiate. The EU is sending diplomats. And Ohgi says there is a line of Japanese officials outside demanding to help rebuild the government." She pauses. "What do we do now, Zero?"\n\nYou look at Suzaku. He looks at you. Two boys who caught frogs together, who fought a war on opposite sides, who finally chose to trust each other.\n\n"We do the boring part," you say. "We govern."\n\nNunnally is safe. Brought home. She holds your hand and cries. She does not ask about the war. She just says, "You came back."\n\nThe mask goes into a drawer. Zero is a symbol now, not a person. And Lelouch vi Britannia — the demon, the king, the brother — gets to live.\n\nIt is not the ending you planned. It is better.`,scene:'end',mood:'#2a0845',ending:'The Alliance Endures',characters:['Suzaku','CC','Kallen','Nunnally'],choices:[]};

// ---- ARC 4B: BLACK KNIGHTS CIVIL WAR ----

CG_NODES['cg_identity_exposed'] = {text:`The Black Rebellion is at its peak. Your forces are breaching the inner settlement. Victory is hours away.\n\nThen every screen in Tokyo lights up with Prince Schneizel's face.\n\n"People of Area 11. Members of the Black Knights. I have a gift for you — the truth about the man behind the mask."\n\nFootage plays. Security cameras, intercepted communications, DNA analysis. Your face. Your name. Lelouch vi Britannia. Exiled prince of the very empire the Black Knights swore to destroy.\n\n"Your liberator," Schneizel continues, his voice dripping with polished sincerity, "is Britannian royalty. He has been playing you from the beginning. Every battle, every sacrifice — puppets dancing for a prince who sees you as pieces on his personal chessboard."\n\nThe Black Knights' command channel explodes. Ohgi's voice, cracking: "Zero... is this true?"\n\nKallen stares at your face on the screen. Her Guren's hands go slack.\n\nTohdoh is silent. That is worse.\n\nYou have seconds before the army you built tears itself apart.`,scene:'horror',mood:'#cc0000',characters:['Ohgi','Kallen','Tohdoh'],effects:{flags:{identity_revealed:true},relationships:{ohgi:-2,kallen:-2}},choices:[{text:'Address the Black Knights directly — own the truth and explain why you did it.',next:'cg_bk_schism',check:{stat:'cha',dc:15,pass:'cg_rally_loyalists',fail:'cg_bk_schism'},effects:{stats:{cha:1}}},{text:'Deny everything — claim Schneizel fabricated the evidence.',next:'cg_bk_schism',check:{stat:'int',dc:14,pass:'cg_rally_loyalists',fail:'cg_bk_schism'},effects:{stats:{int:1}}},{text:'Go silent. Remove the mask. Let them see you and decide.',next:'cg_kallen_choice',effects:{stats:{cou:2}}}]};

CG_NODES['cg_bk_schism'] = {text:`The Black Knights fracture down the middle like a bone under too much pressure.\n\nOhgi takes the radio. His voice is steady — the schoolteacher in him, the one who can command a classroom, surfaces. "All units, this is Ohgi. Zero is... Zero is Lelouch vi Britannia. A prince. He used us. I am assuming field command. All units loyal to Japan — to the REAL cause — rally on my position."\n\nHalf the army pivots. Knightmare Frames that were pointing at Britannian lines now turn inward. Comrades who shared meals and bled together are suddenly aiming weapons at each other.\n\nDiethard screams into his mic: "This is insane! We are mid-battle! Cornelia is STILL out there!"\n\nHe is right. Cornelia, seeing the Black Knights implode, orders an immediate counterattack. Britannian forces surge into the gap.\n\nYou are trapped between your own army and the enemy.\n\nTohdoh contacts you privately. "I will not fire on Japanese soldiers. But I will not follow a Britannian prince either. Give me a reason, Lelouch. One reason to stay."`,scene:'battle',mood:'#cc0000',characters:['Ohgi','Tohdoh','Cornelia'],effects:{relationships:{ohgi:-3},flags:{bk_civil_war:true}},choices:[{text:'Tell Tohdoh the whole truth — your mother, Nunnally, the Emperor. Everything.',next:'cg_rally_loyalists',check:{stat:'cha',dc:13,pass:'cg_rally_loyalists',fail:'cg_bk_civil_battle'},effects:{stats:{cha:1}}},{text:'Forget Tohdoh — grab whoever is still loyal and fight your way out before Cornelia crushes everyone.',next:'cg_bk_civil_battle',effects:{stats:{cou:1,str:1}}}]};

CG_NODES['cg_rally_loyalists'] = {text:`Tohdoh listens. You tell him everything — not as Zero, not with the theatrical voice, but as yourself. Your mother, murdered. Nunnally, blinded and crippled. The Emperor who discarded you both like defective merchandise. The years of hiding. The rage.\n\n"I used the Black Knights. Yes. I gave them a masked general because a Britannian face would never lead a Japanese rebellion. But every battle I planned, every life I spent — it was to destroy the system that destroyed my family. The same system that destroyed yours."\n\nTohdoh is quiet for a long time. Shells explode in the distance. Cornelia's counterattack is gaining ground.\n\n"I lost my students at Itsukushima," Tohdoh finally says. "I have spent years fighting for Japan with nothing but rage and discipline. You gave us organization. Strategy. Victories. The mask was a lie. The results were not."\n\nHe switches to the open channel. "This is Lieutenant Colonel Tohdoh. All units under my command: hold formation. We deal with the identity issue AFTER we survive the battle in front of us. Anyone who turns their weapons on a fellow Black Knight answers to me."\n\nKallen's Guren moves to your flank. She says nothing. But she is there.\n\nYou have lost half the army. Ohgi's faction is retreating to regroup. But the half that remains — the fighters, the killers, the ones who follow results over ideology — they are still yours.`,scene:'battle',mood:'#636e72',characters:['Tohdoh','Kallen'],effects:{stats:{cha:1},relationships:{tohdoh:3,kallen:2}},choices:[{text:'Push forward — take the settlement with the forces you have left and prove your loyalty through victory.',next:'cg_reclaim_command',effects:{stats:{cou:2,int:1}}},{text:'Fall back and regroup — half an army cannot take the settlement, but it can survive to fight another day.',next:'cg_flee_alone',effects:{stats:{per:1,int:1}}}]};

CG_NODES['cg_kallen_choice'] = {text:`You pull off the mask. Not dramatically — no flourish, no speech. You just take it off and let the camera see Lelouch vi Britannia's face.\n\nThe battlefield goes quiet. A strange, terrible quiet — a thousand soldiers processing betrayal in real time.\n\nKallen's Guren walks toward your command unit. Slowly. The radiant wave surger is not charged, but at this range, she does not need it.\n\nHer face appears on your private screen. She has been crying. Kallen Kozuki — who never cries, who fights like fury itself — has tears on her cheeks.\n\n"Was any of it real?" she asks. "The cause. The speeches. The battles where we bled for you. Did you actually care? Or were we just your tools?"\n\nThe honest answer is complicated. The right answer matters more than the honest one. But you are done lying.\n\n"You were both," you say. "I used you. I also fought beside you. I watched people die for a cause I started and I lost sleep over every one. You are not just tools, Kallen. But I cannot pretend I did not treat you like them sometimes."\n\nShe is quiet. Her hand rests on the Guren's controls.\n\n"Ohgi is rallying people against you. Cornelia is attacking. Half the army wants you dead. What do you want me to do?"`,scene:'confrontation',mood:'#cc0000',characters:['Kallen'],effects:{relationships:{kallen:1}},choices:[{text:'"Fight with me. One more time. After that, you can decide what I deserve."',next:'cg_rally_loyalists',check:{stat:'cha',dc:12,pass:'cg_rally_loyalists',fail:'cg_bk_civil_battle'},effects:{relationships:{kallen:2}}},{text:'"Leave. You have earned the right to walk away from this. I have no right to ask you for anything."',next:'cg_flee_alone',effects:{stats:{per:1},relationships:{kallen:3}}}]};

CG_NODES['cg_bk_civil_battle'] = {text:`The nightmare you never planned for: Black Knights killing Black Knights.\n\nOhgi's faction opens fire first — a volley of Knightmare rifles aimed at your command unit. Your remaining loyalists return fire on instinct. Japanese killing Japanese while Britannia watches.\n\nCornelia does not even need to attack. She pulls her forces back to the settlement walls and lets you destroy yourselves.\n\n"Magnificent," she murmurs on an intercepted channel. "Zero's revolution eats itself."\n\nThe battle is brutal and short. Your loyalists are outnumbered — Ohgi has the rank and file, the people who joined because Zero was a SYMBOL. You have the elites — Tohdoh's core unit, Kallen if she stayed, the hardened veterans who follow competence.\n\nBut you cannot bring yourself to use Geass on your own people. Every face behind those cockpits is someone who trusted you.\n\nA stray shot clips your command unit. Warning lights flood the cockpit. The Knightmare is dying.`,scene:'battle',mood:'#cc0000',characters:['Ohgi','Cornelia'],effects:{stats:{cou:1},relationships:{ohgi:-3}},choices:[{text:'Eject and flee — live to fight another day, even if it means leaving everything behind.',next:'cg_flee_alone',effects:{stats:{per:1}}},{text:'Broadcast one final order — ceasefire, unconditional. Surrender yourself to Ohgi to stop the bloodshed.',next:'cg_ending_fractured',effects:{stats:{cou:2}}}]};

CG_NODES['cg_flee_alone'] = {text:`You run.\n\nThe great Zero — the masked revolutionary who shook an empire — runs through back alleys in a torn cape, Geass eye burning, with nothing but C.C. and the clothes on your back.\n\nC.C. keeps pace easily. Immortals do not tire. "This is familiar," she says. "I have watched many Geass users fall. Usually it is slower."\n\n"Comforting."\n\n"It was not meant to be." She hands you a stolen phone. "What now?"\n\nThe Black Knights are Ohgi's now — or what is left of them. Cornelia retook the settlement during the civil war. Japan is worse off than before you started. Every death, every sacrifice, every impossible battle — undone because a prince's face was under the mask.\n\nBut you are alive. You have Geass. And you have something you did not have before: the knowledge of exactly how and why you failed.\n\nThe phone rings. A blocked number.\n\nYou answer. A voice you have never heard — calm, aristocratic, dangerous.\n\n"Lelouch vi Britannia. My name is Schneizel. Your brother. I believe we have much to discuss."`,scene:'aftermath',mood:'#636e72',characters:['CC'],effects:{relationships:{cc:2},flags:{schneizel_contact:true}},choices:[{text:'Hear Schneizel out — he exposed you, but he also might be the key to your next move.',next:'cg_ending_exile',effects:{stats:{int:2}}},{text:'Hang up. Schneizel is the enemy. Rebuild alone, from nothing if you have to.',next:'cg_ending_exile',effects:{stats:{cou:1,per:1}}}]};

CG_NODES['cg_reclaim_command'] = {text:`You drive forward with half an army. It should not work. The math says it cannot work. But you have something Cornelia's forces and Ohgi's faction do not — total coordination between your best units.\n\nTohdoh's Holy Swords carve a path through the settlement's western gate. Kallen's Guren breaks the inner line. And you — reading the battlefield like a chessboard — pour your remaining forces through every gap.\n\nOhgi's faction, still in disarray, watches as you bypass them entirely. You are not fighting the mutineers. You are ignoring them. Winning the war while they argue about who should lead it.\n\nCornelia intercepts you at the government bureau. Her Gloucester against your command unit. She is a superior pilot. You are a superior strategist.\n\nThe duel is chess at 200 kilometers per hour.`,scene:'battle',mood:'#cc0000',characters:['Cornelia','Tohdoh','Kallen'],choices:[{text:'Outmaneuver Cornelia — use the terrain and your knowledge of her fighting style.',next:'cg_ending_reclaimed',check:{stat:'int',dc:14,pass:'cg_ending_reclaimed',fail:'cg_ending_fractured'},effects:{stats:{int:1}}},{text:'Call Kallen for backup — you do not need to win alone.',next:'cg_ending_reclaimed',effects:{stats:{cha:1},relationships:{kallen:2}}}]};

CG_NODES['cg_ending_exile'] = {text:`You disappear.\n\nZero is declared dead by the Black Knights, by Britannia, by the world. Lelouch vi Britannia is added to a list of war criminals. Your face appears on wanted posters alongside the worst of the rebellion's excesses.\n\nBut you are not dead. You are in a safehouse in the Chinese Federation, eating bad takeout and staring at a map of the world.\n\nC.C. sits across from you. She has seen this before — the fall, the exile, the long dark planning. "Most people would quit," she says.\n\n"I am not most people."\n\n"No. You are a seventeen-year-old with a god complex and a magic eye. Much worse."\n\nYou almost laugh. Almost.\n\nThe world thinks Zero is dead. The Black Knights are fractured under Ohgi's well-meaning but uninspired leadership. Britannia is tightening its grip. Everything you built is ash.\n\nBut ash is fertilizer. And you have time.\n\nYou start planning. Not a rebellion this time — a revolution. Bigger. Smarter. With no mask to hide behind and no lies to be exposed. Just you, your mind, and the Geass.\n\nSix months later, a signal goes out to every resistance cell on the planet. No face. No name. Just a chess piece — a black king — and four words:\n\n"Zero is not dead."\n\nThe game begins again.`,scene:'end',mood:'#636e72',ending:'Exile\'s Return',characters:['CC'],choices:[{text:'Six months later — the signal is answered. Continue the story.',next:'cg_ending_exile_return',effects:{stats:{int:1,cou:1}}}]};

CG_NODES['cg_ending_fractured'] = {text:`You surrender.\n\nYou step out of your ruined Knightmare, hands raised, mask discarded in the wreckage. Ohgi's soldiers surround you. Rifles aimed at the prince who pretended to be their savior.\n\nOhgi walks toward you. He looks exhausted. Heartsick. "Why?" he asks. "You could have just TOLD us. We might have understood. A Britannian prince who wanted to destroy his own empire — that is a story people could believe in. Why the lies?"\n\n"Because the truth was not enough." You meet his eyes. "A masked revolutionary inspires. A Britannian prince leading Japanese soldiers is a puppet show. I needed the myth more than the truth."\n\n"And now the myth is dead. And so is the rebellion."\n\nHe is right. Cornelia retakes the settlement within hours. The Black Knights dissolve — Ohgi negotiates amnesty for the rank and file in exchange for your capture. It is the best deal he can get.\n\nYou are handed to Britannia. A military tribunal. A cell.\n\nBut in the cell, you smile. Because Schneizel made a mistake. He exposed you to break the rebellion, but he also showed the world that a Britannian prince chose Japan over his own empire. That idea — loyalty to justice over blood — does not die in a cell.\n\nKallen visits once. "I hate you," she says through the glass.\n\n"I know."\n\n"I also think you were the best commander we ever had. And I hate that too."\n\nThe rebellion is over. But the revolution — the idea — is just beginning. Someone else will pick up the mask. Someone always does.\n\nZero is dead. Long live Zero.`,scene:'end',mood:'#2a0845',ending:'The Mask Endures',characters:['Ohgi','Kallen','Cornelia'],choices:[{text:'In the cell, Schneizel comes with an offer. Continue the story.',next:'cg_ending_fractured_rise',effects:{stats:{int:1}}}]};

CG_NODES['cg_ending_reclaimed'] = {text:`Cornelia falls.\n\nNot dead — you disabled her Gloucester's limbs with surgical precision, pinning it against the bureau wall. She ejects, landing on the steps of her own government building, sword drawn.\n\n"Finish it, Zero. Or Lelouch. Or whatever you call yourself."\n\n"I am both," you say, stepping from your Knightmare. Mask off. Face bare. "And I call this finished."\n\nShe does not lower her sword. But she does not swing it either.\n\nThe settlement is yours. Won with half an army and a fractured rebellion, against a military genius and your own mutineers. It should not have been possible. But you have always been better at impossible than probable.\n\nOhgi's faction arrives too late to stop you and too early to pretend they helped. They stand at the gates, watching their expelled leader hold the prize.\n\nOhgi requests a meeting. You grant it.\n\n"I was wrong about your motives," he admits. "But I was not wrong about the deception."\n\n"You were right," you say. "I lied. I manipulated. I treated this rebellion as my personal war. And I would do it again, because it worked. But I will not lie anymore. You know who I am. Everyone does. So let me ask you, Ohgi — will you follow Lelouch vi Britannia? Not Zero. Not a mask. Me."\n\nThe silence stretches. Then Ohgi extends his hand.\n\nThe Black Knights reunite. Scarred, suspicious, watching you with eyes that no longer hold blind faith. But they follow. And blind faith was always the wrong foundation anyway.\n\nNunnally is recovered from the homeland. She holds your face in her hands — blind, but seeing more than anyone. "You sound tired, brother."\n\n"I am. But I am not done."\n\nThe mask goes in a museum. Japan is free. And for the first time, you lead without hiding.\n\nIt is harder. It is honest. It is enough.`,scene:'end',mood:'#d4a017',ending:'Unmasked Revolution',characters:['Ohgi','Kallen','Cornelia','Nunnally'],choices:[]};

CG_NODES['cg_geass_control'] = {text:`The Geass is growing.\n\nWhat started as a power you could activate at will has become a pressure behind your left eye — constant, insistent, hungry. C.C. warned you this would happen. The Geass evolves. It wants to be permanent.\n\nYou notice the signs: a student obeys your offhand request without hesitation. A shopkeeper gives you free food when you mention being hungry. Small things. Coincidences you cannot afford to ignore.\n\n"The Geass will eventually activate without your conscious control," C.C. explains, unusually serious. "Every Geass user faces this. Most are consumed by it. The power becomes them — they cannot tell where their will ends and the Geass begins."\n\n"How do I stop it?"\n\n"Discipline. Focus. Or..." she touches her forehead, where her own Code resides. "You take the next step. Become immortal. Lose the Geass but gain the Code."\n\n"And become like you? Wandering for centuries, handing out contracts?"\n\n"There are worse fates. Like accidentally commanding someone you love to die."\n\nThe thought hits like ice water. Nunnally. Kallen. Suzaku. If the Geass activates during a conversation — a stray word, an idle thought — the consequences are irreversible.\n\nYou need to master this. Now.`,scene:'planning',mood:'#cc0000',characters:['CC'],effects:{relationships:{cc:2}},choices:[{text:'Train with C.C. — learn to suppress the Geass through sheer willpower.',next:'cg_euphemia',check:{stat:'per',dc:13,pass:'cg_euphemia',fail:'cg_euphemia'},effects:{stats:{per:2}}},{text:'Limit contact with people — isolate yourself to reduce the risk.',next:'cg_euphemia',effects:{stats:{int:1},relationships:{kallen:-1,ohgi:-1}}},{text:'Embrace it — a permanent Geass means never needing to remove the mask.',next:'cg_euphemia',effects:{stats:{cou:1,str:1}}},{text:'C.C. mentions a facility — the Geass Directorate. To understand this power, go to its source.',next:'cg_vv_order',effects:{stats:{int:1}}}]};

// ---- ARC 5: EUPHEMIA'S SALVATION — ALTERNATE TIMELINE ----

CG_NODES['cg_euphemia_saved'] = {text:`You see it happening — the Geass activating, the words leaving your mouth, Euphemia's eyes going blank. But this time, you are faster. This time, the training with C.C. pays off.\n\nYou clamp your hand over your left eye. The Geass fires — you feel it burn through your palm, scorching your skin — but your hand absorbs the command. The power discharges harmlessly into your own flesh.\n\nEuphemia blinks. "Lelouch? Are you alright? Your hand is bleeding."\n\n"Fine," you gasp, the pain white-hot. "I am fine. Just... a headache."\n\nShe looks at you with those impossibly kind eyes. The eyes of a princess who genuinely wants peace. The eyes you nearly turned into a weapon.\n\nThe Special Administrative Zone proceeds. Against every strategic instinct you have, against every calculation that says this undermines the rebellion — you let Euphemia try.\n\nAnd it works.\n\nThe Japanese line up by the thousands. They receive ID cards with their real names. Not "Eleven" — their names. Families weep. Children who have never been called anything but a number hear their heritage spoken aloud for the first time.\n\nKallen contacts you, furious. "Zero! The Special Zone is WORKING. People are leaving the resistance to register. We are losing soldiers every hour!"\n\n"I know."\n\n"Then DO something!"\n\nYou watch Euphemia on the stage, smiling as she hands a card to an elderly man who is crying too hard to read his own name.\n\n"Maybe," you say quietly, "this is something."`,scene:'revelation',mood:'#d4a017',characters:['Euphemia','Kallen'],effects:{stats:{per:2},relationships:{euphemia:3,kallen:-1},flags:{euphemia_alive:true}},choices:[{text:'Support the Special Zone openly as Zero — redirect the rebellion toward political reform.',next:'cg_zero_diplomacy',effects:{stats:{cha:2,int:1}}},{text:'Work behind the scenes — let Euphemia be the face while you handle the threats she cannot see.',next:'cg_cornelia_alliance',effects:{stats:{int:2}}}]};

CG_NODES['cg_zero_diplomacy'] = {text:`Zero stands before a crowd of Japanese and Britannians — the first mixed audience to hear the masked revolutionary speak without weapons drawn.\n\n"I am Zero. I have fought Britannia with fire and steel. Today, I fight with something more dangerous: trust."\n\nThe crowd murmurs. Black Knights shift nervously. Britannian soldiers grip their rifles.\n\n"Princess Euphemia has offered what I could not — a path to dignity without bloodshed. I am not naive. I know the Empire's history. I know promises break. But I also know that some promises are worth the risk of believing."\n\nYou extend your hand toward Euphemia on the stage. She takes it. The photograph — Zero's gloved hand clasping a Britannian princess's — becomes the most reproduced image in Area 11's history.\n\nBehind the scenes, the calculation is brutal. If the Special Zone fails, you have positioned yourself to absorb the disillusioned into the Black Knights. If it succeeds, you have a seat at the table when the new order is written.\n\nCornelia watches from the government bureau, jaw tight. She does not trust you. She does not trust this. But she trusts Euphemia — and Euphemia is radiant.\n\n"You are gambling with my sister's life," Cornelia tells you in a private meeting.\n\n"I am gambling with everyone's life. That is what leaders do."\n\n"If anything happens to her—"\n\n"Then you and I will share the same enemy. And I suspect that enemy will not survive us both."`,scene:'planning',mood:'#d4a017',characters:['Euphemia','Cornelia'],effects:{stats:{cha:1,int:1},relationships:{euphemia:2,cornelia:1}},choices:[{text:'Build the diplomatic framework — turn the Special Zone into a model for all Areas.',next:'cg_chinese_federation',effects:{stats:{int:2}}},{text:'Cornelia almost respects you. Cultivate that — you need military allies as much as political ones.',next:'cg_cornelia_alliance',effects:{stats:{cha:1},relationships:{cornelia:2}}}]};

CG_NODES['cg_cornelia_alliance'] = {text:`Cornelia li Britannia is not a woman who makes alliances lightly. She is a soldier — direct, brutal, and unflinchingly loyal to the Empire. Or so you thought.\n\nThe private meeting happens in a neutral location — a bombed-out cathedral on the border between the settlement and the ghetto. Poetic. Neither of you comments on the symbolism.\n\n"I have read your military tactics," Cornelia says, arms crossed. "Narita. The port battle. The prison break. You are brilliant. You are also reckless, sentimental, and dangerously theatrical."\n\n"Coming from the woman who pilots a purple Knightmare with a cape."\n\nShe almost smiles. Almost.\n\n"Schneizel is moving against Euphemia's Special Zone," she says, and the almost-smile vanishes. "Our brother does not believe in peace — he believes in control. The Special Zone threatens his political position. He will sabotage it — subtly, deniably — and blame the failure on Japanese 'ingratitude.'"\n\n"And you want to stop him."\n\n"I want to protect my sister. If that means working with the masked terrorist who has been dismantling my military operations for six months..." She uncrosses her arms. "Then I work with the masked terrorist."\n\nThe alliance is fragile, suspicious, and built on the thinnest possible foundation: two people who love Euphemia more than they hate each other.\n\nC.C., eating pizza in the corner of the cathedral, observes: "This is the strangest chess game I have ever seen. And I have lived through several centuries of them."\n\n"Shut up and eat your pizza," you and Cornelia say simultaneously.\n\nYou look at each other. Something shifts.`,scene:'planning',mood:'#636e72',characters:['Cornelia','CC'],effects:{stats:{cha:1,int:1},relationships:{cornelia:3,cc:1},flags:{cornelia_allied:true}},choices:[{text:'Plan a joint defense of the Special Zone against Schneizel\'s sabotage.',next:'cg_schneizel_chess',effects:{stats:{int:2}}},{text:'Use the alliance to reach the Chinese Federation — Cornelia has diplomatic channels you lack.',next:'cg_chinese_federation',effects:{stats:{int:1,cha:1}}}]};

CG_NODES['cg_schneizel_chess'] = {text:`Schneizel el Britannia does not fight with armies. He fights with information, leverage, and the patient dismantling of everything you build.\n\nThe first move is elegant: a series of "incidents" in the Special Zone. Britannian businesses claim Japanese workers stole from them. Japanese residents report harassment by soldiers who conveniently lack identification. Each incident is small. Each one erodes trust.\n\n"He is salting the earth," you tell Cornelia. "Creating a narrative of failure so that when the Zone collapses, everyone says it was inevitable."\n\n"I know my brother's methods," Cornelia replies. "But knowing them and stopping them are different things. Schneizel controls the media bureau. He has agents inside the Zone administration. And he has something we do not — the Emperor's ear."\n\nYou challenge Schneizel directly. Not with weapons — with a chess game. Broadcast publicly. The Second Prince against Zero, playing for the soul of the Special Zone.\n\nThe game is held in the settlement's grand hall. Thousands watch. Schneizel sits across from you, immaculate, smiling his reptilian smile.\n\nYou play white. He plays black. The irony is not lost on either of you.\n\nFifty-seven moves in, the board is a graveyard. Schneizel has sacrificed pieces with an abandon that mirrors his political strategy — willing to lose anything to create the position he wants.\n\nThen you see it. His endgame. He is not trying to win the chess match. He is trying to make you LOSE PUBLICLY — to demonstrate that Zero can be beaten, that the myth is just a man who makes mistakes.\n\nThe board is a metaphor. And the audience is the real game.\n\nYou have two moves left. One wins the chess game but proves his point — Zero, desperate, clawing for victory. The other is a draw — a stalemate that denies him the narrative he wants.\n\nOr there is a third option. You could flip the board entirely.`,scene:'confrontation',mood:'#2a0845',characters:['Schneizel','Cornelia'],effects:{stats:{int:2}},choices:[{text:'Accept the draw. Deny Schneizel his narrative. A stalemate is a victory when the alternative is a spectacle.',next:'cg_chinese_federation',effects:{stats:{int:1,per:1}}},{text:'Flip the board. Stand up. Address the audience directly — make the chess game irrelevant.',next:'cg_schneizel_exposed',effects:{stats:{cha:2,cou:1}}}]};

CG_NODES['cg_schneizel_exposed'] = {text:`You stand. The chess pieces rattle.\n\n"This game is over," you announce to the hall. Your digitally altered voice fills every corner. "Not because either of us won — but because this was never about chess."\n\nSchneizel's smile freezes. Just for a microsecond.\n\n"Prince Schneizel challenged Zero to a game. A spectacle. Entertainment. But while we moved pieces on a board, his agents moved pieces in the Special Zone. Three fabricated incidents this week alone. A forged theft report. A staged assault. A planted news story about Japanese 'unrest' that never happened."\n\nYou pull out a folder — evidence compiled by Cornelia's intelligence network and your own Geass-extracted confessions. You spread it on the chess board, covering the pieces.\n\n"This is the real game Schneizel plays. Not chess. Sabotage. He does not want the Special Zone to fail because he fears Japanese freedom. He wants it to fail because its SUCCESS threatens his political position. Peace is bad for princes who build their careers on war."\n\nThe hall erupts. Cameras flash. Schneizel's composure holds — barely — but you can see the calculation behind his eyes. You have forced him to respond publicly, in real time, without preparation.\n\n"These are fabrications—" he begins.\n\nCornelia steps forward. In full military regalia. The Witch of Britannia, standing beside Zero.\n\n"They are not fabrications," she says. "I verified them personally. My brother is undermining our sister's work. And I will not allow it."\n\nThe political earthquake registers on every seismograph in the Empire.`,scene:'confrontation',mood:'#d4a017',characters:['Schneizel','Cornelia','Euphemia'],effects:{stats:{cha:2,int:1},relationships:{cornelia:2,schneizel:-3},flags:{schneizel_exposed:true}},choices:[{text:'Press the advantage — use the momentum to expand the Special Zone model to other Areas.',next:'cg_chinese_federation',effects:{stats:{int:1,cha:1}}},{text:'Schneizel will retaliate. Prepare defenses — the next attack will not be political.',next:'cg_suzaku_redemption',effects:{stats:{per:2}}}]};

CG_NODES['cg_chinese_federation'] = {text:`The Chinese Federation — the third superpower, sprawling across Asia — is rotting from within. The Empress Tianzi is a child, a figurehead controlled by the High Eunuchs who rule in her name. The people starve while the court feasts.\n\nYour contact is Li Xingke — a military officer dying of a terminal illness, devoted to the Empress, and planning a coup he does not have the forces to execute alone.\n\n"Zero," Xingke says via encrypted channel. His voice is calm despite the coughing. "I have heard what you did in Area 11. The Special Zone. The alliance with Cornelia. You turned enemies into allies through sheer audacity."\n\n"I turned enemies into allies through necessity. Audacity was just the delivery method."\n\n"I need your audacity. The High Eunuchs are negotiating with Britannia — they plan to sell the Federation's sovereignty in exchange for personal power. They will hand Tianzi to a Britannian prince as a political marriage. She is thirteen years old."\n\nThe anger is immediate. Visceral. A child used as currency by the powerful — it hits close to home.\n\nKallen reviews the intelligence. "The Federation's military is ten times our size. Even with Cornelia's support, we cannot fight a war on that scale."\n\n"We do not need to fight the military," you reply. "We need to fight the Eunuchs. Six men. Six targets. Six commands."\n\nYour Geass eye pulses. Six commands would be enough to topple a government.\n\nBut C.C. warned you: the Geass is unstable. Every use risks losing control entirely. Six commands in rapid succession could push you past the point of no return.`,scene:'planning',mood:'#636e72',characters:['Kallen','CC'],effects:{stats:{int:1},flags:{chinese_federation_arc:true}},choices:[{text:'Use the Geass surgically — one Eunuch at a time, carefully, with recovery periods between.',next:'cg_xingke_coup',effects:{stats:{int:2,per:1}}},{text:'Find another way. Xingke has military support — combine it with the Black Knights for a conventional coup.',next:'cg_xingke_coup',effects:{stats:{cou:1,str:1}}}]};

CG_NODES['cg_xingke_coup'] = {text:`The Vermilion Forbidden City. Heart of the Chinese Federation. A palace of jade and gold where a child Empress sits on a throne too large for her, surrounded by men who sold her future for political favors.\n\nXingke's forces strike from within. The Black Knights provide external pressure — Kallen's Guren and Tohdoh's strike force creating a perimeter that prevents the Eunuchs' private armies from reinforcing.\n\nYou infiltrate the palace personally. C.C. at your side. The corridors are labyrinthine — designed to confuse invaders — but you have the floor plans, courtesy of Diethard's intelligence network.\n\nThe High Eunuchs are in the throne room, finalizing the marriage contract with a Britannian envoy. Schneizel's envoy, naturally. Even here, your brother's fingerprints are on the betrayal.\n\nXingke crashes through the doors with his personal guard. Swords drawn. The man is dying — you can see it in the blood flecks on his lips — but he fights like someone who has already accepted death and decided to spend it well.\n\n"Empress Tianzi!" he calls. "I swore to protect you. Forgive me for taking so long."\n\nThe child Empress looks at him with eyes that hold more understanding than any thirteen-year-old should possess. "Xingke. I knew you would come."\n\nThe Eunuchs panic. They call for guards. The guards look at Xingke — the hero of the people, the dying soldier — and they look at the Eunuchs — bloated, corrupt, selling their nation.\n\nThe guards lay down their weapons.\n\nThe coup takes forty minutes. Not a single shot fired inside the palace. Outside, the Eunuchs' mercenary forces scatter when they realize their employers are in chains.\n\nTianzi takes the throne — truly, this time. Xingke stands behind her, coughing blood into a handkerchief, smiling.`,scene:'battle',mood:'#d4a017',characters:['Kallen','CC'],effects:{stats:{int:1,cha:1},flags:{federation_liberated:true}},choices:[{text:'Forge a formal alliance between the liberated Chinese Federation and the Special Zone.',next:'cg_united_front',effects:{stats:{cha:2,int:1}}},{text:'Xingke is dying. Help him — Britannia has medical technology that could save his life.',next:'cg_suzaku_redemption',effects:{stats:{cha:1},relationships:{cornelia:1}}}]};

CG_NODES['cg_suzaku_redemption'] = {text:`Suzaku Kururugi has been silent for weeks. The Knight of Seven — Britannia's weapon, the pilot of the Lancelot — has watched the Special Zone succeed, watched Cornelia ally with Zero, watched the Chinese Federation fall to revolution. Everything he believed in — changing the system from within — has been proven unnecessary by the people who burned the system from without.\n\nHe finds you at the Kururugi shrine. Your childhood home. The place where two boys used to catch frogs and argue about justice.\n\nHe is not wearing his uniform. Just civilian clothes. He looks smaller without the white cape.\n\n"You were right," he says. The words come out like shrapnel being pulled from a wound. "The system could not be reformed. I climbed and climbed and all I found was more corruption. More compromise. More excuses for why justice had to wait."\n\n"I was not entirely right," you reply. "Euphemia proved that. The Special Zone works. Not because I destroyed the system — because she built something better inside it."\n\n"And I helped no one. I arrested rebels who should have been free. I fought the Black Knights while they were fighting for justice. I—" His voice cracks. "Euphemia asked me to protect the Zone. I told her I could not. That my oath to Britannia came first. And she said..." He closes his eyes. "'Then your oath is wrong, Suzaku. Change it.'"\n\nThe frog pond is still here. Smaller than you remember. Everything from childhood is smaller than you remember.\n\n"I want to change my oath," Suzaku says. "But I do not know if I deserve to."\n\nYou look at your oldest friend. The boy who killed his own father to stop a war. Who carried that guilt into a death wish. Who served an empire he hated because he believed in doing the right thing through the wrong system.\n\n"Nobody deserves anything," you say. "We just choose. And keep choosing. Every day."`,scene:'emotional',mood:'#636e72',characters:['Suzaku'],effects:{stats:{cha:1},relationships:{suzaku:4},flags:{suzaku_redeemed:true}},choices:[{text:'Welcome Suzaku home. The Lancelot fighting alongside the Guren would be unstoppable.',next:'cg_united_front',effects:{stats:{cou:1},relationships:{suzaku:2}}},{text:'Give him time. Redemption is not a handshake — it is a process.',next:'cg_united_front',effects:{stats:{per:1},relationships:{suzaku:1}}}]};

CG_NODES['cg_united_front'] = {text:`The United Federation of Nations. Not a rebellion — a coalition. Not conquered peoples begging for freedom — sovereign nations demanding it.\n\nJapan. The Chinese Federation. The EU fragments that have broken from Britannian pressure. India. Half of Africa. A patchwork quilt of liberated and liberating peoples, stitched together by diplomacy, desperation, and the improbable alliance between a masked revolutionary, a Britannian princess, and a dying Chinese general.\n\nYou stand before the assembled delegates. Zero's mask is on, but the voice beneath it has changed. Less theatrical. More real.\n\n"This federation is not my creation. It is not Euphemia's, or Cornelia's, or Xingke's. It belongs to every person who chose to believe that the world could be different. I am a symbol. Symbols do not govern. People do."\n\nThe charter is signed. Forty-seven nations. A mutual defense pact. A commitment to self-determination. It is imperfect — there are territorial disputes, economic imbalances, old grudges that no charter can erase.\n\nBut it exists. And Britannia, for the first time in its imperial history, faces a unified world.\n\nEmperor Charles zi Britannia watches from his throne in Pendragon. His Geass-clouded eyes see further than any satellite — into the hearts of every person who signed that charter.\n\n"They think unity will save them," he murmurs to his knight. "They do not understand. I will give them unity. True unity. The Ragnarok Connection will merge every human consciousness into one. No nations. No borders. No lies. One mind. One truth. One world."\n\nThe final battle is not against an army. It is against an idea — an idea held by a father who would rather destroy human individuality than admit his children proved him wrong.\n\nSchnizel sends a message: "The Emperor is activating the Sword of Akasha. You have seventy-two hours before human consciousness ceases to exist as we know it."`,scene:'planning',mood:'#2a0845',characters:['Kallen','Suzaku','Cornelia'],effects:{stats:{int:1,cha:2},flags:{ufn_formed:true}},choices:[{text:'Assault the Sword of Akasha with the full might of the United Federation.',next:'cg_ending_dawn',effects:{stats:{cou:2,int:1}}},{text:'Go alone with C.C. This is a family matter — father against son, Geass against Geass.',next:'cg_ending_dawn',effects:{stats:{cou:2,per:1}}}]};

CG_NODES['cg_ending_dawn'] = {text:`The Sword of Akasha exists between worlds — a cathedral of light and thought where the collective unconscious of humanity converges. You stand before your father, the 98th Emperor of Britannia, in a place where lies are impossible.\n\nCharles zi Britannia is enormous in this space. Not physically — conceptually. He IS the system. The Empire. The ideology of strength and domination given human form.\n\n"You cannot stop Ragnarok," he says. "I will give humanity what it truly wants — an end to misunderstanding. An end to deception. One mind. One truth."\n\n"You will give humanity a cage," you reply. "A gilded, truthful cage where no one can think a thought that is not shared, feel a feeling that is not collective, dream a dream that is not approved."\n\n"And your alternative? More war? More lies? More children dying for causes they do not understand?"\n\n"My alternative is CHOICE. Messy, stupid, glorious choice. The right to be wrong. To lie. To change your mind. To love someone for reasons that make no sense to anyone else."\n\nC.C. stands beside you. Suzaku stands beside you. Kallen, Cornelia, Euphemia's hope, Xingke's sacrifice, Ohgi's stubborn decency — all of them behind you. Not because you commanded them. Because they chose.\n\n"I command the collective unconscious," you say, Geass blazing. "DO NOT STOP THE MARCH OF TIME."\n\nThe Emperor fights. The Sword of Akasha trembles. But your Geass — the Geass born from the desire to command, wielded by someone who learned to ask instead — prevails.\n\nCharles dissolves. Not in agony. In confusion. He genuinely does not understand how choice defeated certainty.\n\nThe Sword of Akasha collapses. You fall back to reality — to a world that is fractured, uncertain, and free.\n\nThere is no grand sacrifice. No Zero Requiem. No dying on a throne for symbolism. Instead, there is the quiet, unglamorous work of building something from the rubble.\n\nSuzaku becomes the head of the joint military council. Kallen leads the Japan reconstruction effort. Cornelia — astonishingly — becomes the first Britannian to formally apologize for the occupation. Euphemia's Special Zone model expands across the former Empire.\n\nYou remove the mask. Publicly. On live television. Lelouch vi Britannia shows his face to a world that already suspected.\n\nThe reactions are mixed. Some cheer. Some rage. Most just stare, processing the fact that their liberator was seventeen years old.\n\nC.C. finds you on the roof that evening. She has pizza. She always has pizza.\n\n"The contract is fulfilled," she says. "You changed the world."\n\n"And your wish?"\n\nShe looks at you with those ancient golden eyes. "My wish was to be loved by someone who knew what I am. An immortal witch who has lived too long and lied too much." She pauses. "Do you?"\n\n"Do I what?"\n\n"Know what I am."\n\n"Yes."\n\n"And?"\n\nYou take the pizza box from her hands. "And I think we should eat this before it gets cold. We have a world to rebuild tomorrow."\n\nShe smiles. It is the first genuine smile you have seen from an immortal.\n\nNunnally is safe. She sees — truly sees, her sight restored — for the first time in years. Her first sight is your face.\n\n"Brother," she says. "You look tired."\n\n"I am. But the good kind of tired. The kind you feel after finishing something that mattered."\n\nThe dawn comes. Not the dawn of an empire. Not the dawn of a revolution.\n\nJust dawn. Ordinary. Golden. Free.\n\nAnd for the first time since a green-haired girl took his hand in a warehouse and asked if he wanted power, Lelouch vi Britannia watches the sunrise without planning anything.\n\nIt is enough.`,scene:'end',mood:'#1a3a1a',ending:'A Gentler Dawn',characters:['CC','Suzaku','Kallen','Cornelia','Nunnally','Euphemia'],choices:[]};

CG_NODES['cg_ending_exile_return'] = {text:`Six months in the Chinese Federation. Six months of bad takeout, worse intelligence, and C.C.'s increasingly pointed observations about your personal hygiene.\n\nBut the planning is done. The new rebellion is not a rebellion at all — it is a movement. Decentralized. Leaderless. Every cell operates independently, connected by ideology rather than command structure. You learned from your failure: an army that depends on one masked man dies when the mask falls.\n\nThe signal goes out: a black king, broadcast to every resistance frequency on Earth. Zero is not dead.\n\nThey come. Not to you — to each other. Former Black Knights finding local resistance cells. Japanese refugees connecting with Chinese dissidents. EU partisans linking with African liberation movements. A web without a spider.\n\nYou coordinate from the shadows. No mask. No cape. Just encrypted messages and strategic guidance sent from a safehouse that smells like pizza and regret.\n\nKallen contacts you first. "I knew you were alive. You are too stubborn to die."\n\n"I prefer 'strategically persistent.'"\n\n"I prefer 'absolute bastard who abandoned his army.' But I am glad you are back."\n\nOhgi sends a single message: "I am sorry. Come home."\n\nSuzaku sends nothing. But the Lancelot is seen on three separate occasions engaging Britannian forces independently. Someone changed sides.\n\nOne year after your exile, the United Federation of Nations forms — not around Zero, but around the idea of Zero. Freedom. Self-determination. The right of every person to choose their own path.\n\nYou attend the founding ceremony. No mask. No disguise. Just Lelouch vi Britannia, standing in the back row, watching the world he helped create take its first steps without him.\n\nC.C. stands beside you. "You could lead them. They would follow."\n\n"That is exactly why I should not."\n\nShe takes your hand. An immortal witch and an exiled prince, watching history happen from the cheap seats.\n\n"What now?" she asks.\n\n"I hear the Chinese Federation has excellent pizza delivery."\n\n"It does not."\n\n"Then we will fix that first."\n\nThe king stepped off the board. The game continues without him. And for once, that is exactly how it should be.`,scene:'end',mood:'#636e72',ending:'The King Steps Down',characters:['CC','Kallen'],choices:[{text:'But the Federation faces a new crisis — and Schneizel has built something terrible in the sky.',next:'cg_schneizel_gambit',effects:{stats:{int:1}}}]};

CG_NODES['cg_ending_fractured_rise'] = {text:`The cell is small. The food is adequate. The guards are professional. Britannia treats its political prisoners with a clinical efficiency that is somehow worse than cruelty.\n\nYou have been here for three months. No Geass — they fitted you with a contact lens that blocks the sigil. No visitors except Kallen's single, devastating visit. No information about the outside world.\n\nThen the cell door opens. Not at the scheduled time. Not with the usual guard.\n\nSchnizel stands in the doorway. Immaculate. Smiling.\n\n"Hello, Lelouch. I have a proposition."\n\nHe tells you what has happened: the Black Knights collapsed without you. Ohgi tried to lead but lacked the strategic mind. Cornelia has been reassigned to the EU front. The Special Zone — Euphemia's dream — was dissolved by Imperial decree.\n\nJapan is worse than before. The occupation has intensified. The resistance is dead.\n\n"Unless," Schneizel says, "someone resurrects it. Someone with a mind for strategy and a power that can turn any chess piece on the board."\n\n"You want me to restart the rebellion."\n\n"I want you to WIN the rebellion. Under my guidance. With my resources. In exchange, when the Empire falls — and it will fall, brother, I have seen to that — I take the throne. Peacefully. Reformatively. A new Britannia built on merit instead of blood."\n\nEvery instinct screams trap. But every instinct also screams that rotting in a cell while Japan burns is worse.\n\n"And if I refuse?"\n\n"You stay here. Japan stays occupied. And I find another way." He checks his watch. "You have until morning."\n\nHe leaves. The door locks.\n\nYou stare at the ceiling. C.C.'s voice echoes in your memory: "The Geass responds to your deepest desire." Your deepest desire has not changed. It has never changed.\n\nYou want to destroy the system that crushed your family. Even if that means being used by another part of the system to do it.\n\nIn the morning, when Schneizel returns, you are standing.\n\n"One condition," you say. "Nunnally goes free. Now. Before I agree to anything."\n\nSchneizel nods. "She is already on a plane to the Chinese Federation. I anticipated your answer."\n\nOf course he did. He is a Britannian prince too. Anticipation runs in the family.\n\nThe cell door opens. The game begins again. But this time, you are not the only player who knows the rules. And Schneizel is a far more dangerous partner than any enemy you have faced.\n\nThe king returns to the board. Older. Angrier. And playing a game within a game within a game.\n\nCheck.`,scene:'end',mood:'#2a0845',ending:'The Prince\'s Gambit',characters:['Schneizel','CC'],choices:[{text:'Schneizel reveals his true plan — Damocles. The partnership was always a means to an end.',next:'cg_schneizel_gambit',effects:{stats:{int:1}}}]};

CG_NODES['cg_ending_requiem_aftermath'] = {text:`The world mourns the tyrant. The world celebrates the tyrant's death. Both things are true simultaneously, and neither captures what actually happened.\n\nSuzaku wears the mask of Zero. He governs with quiet competence — the policies are yours, drafted in secret during the final months, designed to dismantle the systems of oppression you spent your life fighting. Suzaku implements them with the moral authority of the hero who "killed" the demon emperor.\n\nNunnally inherits the Britannian throne. She rules with the kindness Euphemia dreamed of, backed by the strategic framework you left behind. She knows the truth — that her brother orchestrated his own assassination to unite the world in hatred of a common enemy. She carries that knowledge like a stone in her chest.\n\nKallen tends a grave in a Japanese cemetery. There is no body — it was cremated by Imperial protocol — but she brings flowers every week. Red flowers. She does not know why red.\n\nOhgi becomes Japan's first prime minister. He names the parliamentary building "Zero Hall." He does not explain the irony to anyone who asks.\n\nC.C. wanders. She has been wandering for centuries, and she will wander for centuries more. But sometimes she stops in a particular city, buys a particular brand of pizza, and sits on a particular bench where a boy with a magic eye once told her he would change the world.\n\n"You did change it," she says to no one. "Was it worth it?"\n\nThe wind blows. The pizza is cold. The question has no answer.\n\nBut on a road outside a small village in the countryside, a hay cart creaks along. The driver wears a wide-brimmed hat pulled low over his face. A green-haired woman sits beside him, eating pizza from a box balanced on her knees.\n\n"You are supposed to be dead," C.C. says.\n\n"I am. Lelouch vi Britannia is dead. Zero Requiem was real." He pulls the hat lower. "I am just a farmer now. With a very annoying roommate who eats all my pizza."\n\n"OUR pizza."\n\nThe cart moves on. The world they saved stretches out behind them — imperfect, scarred, and stubbornly, gloriously free.\n\nThe demon emperor is dead.\n\nLong live the farmer.`,scene:'end',mood:'#1a3a1a',ending:'The Farmer and the Witch',characters:['CC','Suzaku','Nunnally','Kallen'],choices:[]};

CG_NODES['cg_nunnally_plea'] = {text:`Nunnally finds you before the final battle. Not physically — she sends a recorded message through channels only a Britannian princess would know.\n\nHer face fills the screen. Blind eyes. Gentle smile. Hands folded in her lap. She looks older than you remember — war ages everyone, even those shielded from its sharpest edges.\n\n"Brother, I know you are Zero. I have known for a long time. The maids whisper. Cornelia's officers whisper louder. And Suzaku... Suzaku's silence told me everything."\n\nYour chest tightens.\n\n"I am not angry. I understand why you did it. You wanted to build a world where I could be safe. Where a blind girl in a wheelchair would not be a liability or a pawn. You wanted to protect me."\n\nShe pauses. Her unseeing eyes stare directly at the camera — directly at you.\n\n"But I do not want to be protected. I want to HELP. I am a princess of Britannia. That title has been used for conquest and cruelty. Let me use it for something else."\n\n"I am recording this because I know you will not let me fight. You never let me fight. But I am telling you — if you are planning something final, something that costs you everything — do NOT do it without giving me a chance to find another way."\n\n"You are my brother. You carried me when I could not walk. You described sunsets I could not see. You read me stories until I fell asleep and then kept reading because you liked the endings."\n\nHer voice cracks.\n\n"Please, Lelouch. Let me carry YOU for once. Let me be strong enough for both of us. That is all I have ever wanted — not safety, not peace, not a gentle world. Just... to be worthy of the brother who gave up everything for me."\n\nThe recording ends.\n\nC.C. watches your face. She says nothing. There is nothing to say.\n\nThe final battle awaits. But Nunnally's words echo: Let me carry you for once.\n\nMaybe the ending does not have to be a sacrifice. Maybe it can be a partnership.`,scene:'emotional',mood:'#636e72',characters:['Nunnally','CC'],effects:{stats:{cha:1},relationships:{nunnally:4}},choices:[{text:'Change the plan. Include Nunnally. The Zero Requiem becomes something new.',next:'cg_ending_dawn',effects:{stats:{cha:2,cou:1}}},{text:'Watch the message again. Then delete it. Some burdens cannot be shared.',next:'cg_ending_king_price',effects:{stats:{per:1},relationships:{nunnally:2}}}]};

CG_NODES['cg_ending_king_price'] = {text:`The throne is cold. You expected that. What you did not expect is how quickly cold becomes normal.\n\nEmperor Lelouch vi Britannia. The Demon Emperor. The man who conquered the world to save it. You sit in Pendragon — the Britannian capital — and issue decrees that reshape civilization.\n\nAbolish the Area system. Dismantle the colonial apparatus. Free every conquered nation. Return sovereignty. Apologize — publicly, formally, in your own voice — for every crime the Empire committed.\n\nThe world does not believe you. Of course it does not. The man who fought his way to the throne through blood and Geass now claims to be a liberator. It sounds like a trap because it sounds exactly like a trap.\n\nYou govern for two years. Long enough to embed the reforms so deeply that no successor can reverse them. Long enough to watch Nunnally smile again. Long enough to eat pizza with C.C. on a balcony overlooking a city that is slowly, grudgingly learning to be free.\n\nThen Zero Requiem.\n\nSuzaku drives the sword home. You designed the angle, the depth, the theatrical blood splatter. Even in death, you are a perfectionist.\n\nBut here is the secret nobody knows: the Code activates at the moment of death. C.C.'s Code — transferred to you in the Sword of Akasha. You do not die. You just stop being alive in any way that matters to the world.\n\nYou wake up in a field. Alone. Immortal.\n\nThe price of changing the world is watching it change without you. The price of immortality is infinity.\n\nC.C. finds you. She always finds you. She has been doing this for centuries — collecting the people who paid too much for their miracles.\n\n"Welcome to eternity," she says. "It is mostly boring. I recommend pizza."\n\nYou laugh. It is the first genuine laugh in two years.\n\nTwo immortals walk into the sunset. Behind them, a world that thinks its savior is dead. Ahead of them, forever.\n\nForever is a long time. But at least the pizza is good.`,scene:'end',mood:'#2a0845',ending:'The Price of Immortality',characters:['CC','Suzaku','Nunnally'],choices:[]};

// ---- ARC 5: SCHNEIZEL'S GAMBIT & DAMOCLES ----

CG_NODES['cg_schneizel_gambit'] = {text:`Schneizel el Britannia does not conquer. He persuades.\n\nThe reports arrive in fragments — intercepted transmissions, terrified diplomats, satellite imagery that defies belief. Your brother has been busy. While you fought for Japan, while you rallied the United Federation, Schneizel was building something in the sky.\n\nDamocles. A floating fortress the size of a city, bristling with FLEIJA warheads — weapons that erase matter itself. Each one capable of annihilating a metropolis. Schneizel has forty-seven of them.\n\nThe broadcast reaches every screen on Earth simultaneously. Schneizel's face — calm, reasonable, handsome in a way that makes his words sound like inevitability.\n\n"I am not declaring war. I am declaring peace. Damocles will hover above the world as a permanent deterrent. Any nation that initiates conflict will be eliminated. Any army that mobilizes will be erased. War is no longer an option — because I have made its cost absolute."\n\nHe pauses. That signature Schneizel pause — timed for maximum impact.\n\n"You may call this tyranny. I call it mathematics. Zero deaths from war, forever, in exchange for one man holding the trigger. The calculus is clear."\n\nC.C. watches the broadcast with you. Her pizza goes cold — the only time you have seen that happen.\n\n"He is not wrong about the math," she says.\n\n"He is wrong about everything else. Peace through terror is not peace. It is a hostage situation with better branding."\n\n"And you plan to stop him how? He has forty-seven city-killer warheads and a flying fortress."\n\nYou stare at the screen. Your brother smiles back — the smile of a man who has already won and is merely waiting for the world to notice.\n\n"I plan to cheat," you say. "It is what I do best."`,scene:'planning',mood:'#2a0845',characters:['CC','Schneizel'],effects:{stats:{int:1},flags:{damocles_threat:true}},choices:[{text:'Infiltrate Damocles from within — use Geass on the crew to seize control.',next:'cg_damocles_infiltration',effects:{stats:{int:2,per:1}}},{text:'Rally the United Federation fleet for a direct assault. Overwhelming force against the fortress.',next:'cg_damocles_assault',effects:{stats:{cou:2,str:1}}}]};

CG_NODES['cg_damocles_infiltration'] = {text:`The plan is insane. You tell C.C. this. She agrees. You proceed anyway.\n\nSchnizel's blind spot has always been his certainty. He accounts for every rational actor — but you are not rational. You are a seventeen-year-old with a magic eye who named himself after a mathematical concept and wears a cape.\n\nThe infiltration team is small: you, C.C., and Sayoko — the ninja maid, which is a phrase that should not exist but does. You enter Damocles through a maintenance shaft that Schneizel's engineers forgot to seal because no human should be able to reach it. Sayoko can.\n\nInside, the fortress is beautiful and terrible. White corridors. Humming FLEIJA warheads arranged in silos like organ pipes. A crew of three hundred operating the most powerful weapon in human history with the quiet efficiency of bank clerks.\n\nYou Geass the first guard. "Take me to the command center." His eyes glaze. He walks. You follow.\n\nSixteen guards. Sixteen commands. Your Geass eye burns with each use — the power is growing unstable, C.C. warned you about this, the boundary between control and madness thinning with every command.\n\nYou reach the command center. Schneizel is there. Of course he is there — he anticipated infiltration. He anticipated YOU.\n\n"Hello, Lelouch." He does not turn from the window. Below, the world stretches out like a game board. "I wondered when you would arrive. I left the maintenance shaft unsealed on purpose. I wanted to have this conversation."\n\nYour blood goes cold. Every step — calculated. Every guard — allowed.\n\n"You cannot Geass me," Schneizel says. "I took precautions." He taps a contact lens in his eye — Geass-canceling technology, developed from Jeremiah's research. "So let us talk instead. Brother to brother. King to king."`,scene:'battle',mood:'#2a0845',characters:['CC','Schneizel'],effects:{stats:{int:1,per:1}},choices:[{text:'Talk. If you cannot command him, you can still outthink him.',next:'cg_schneizel_debate',effects:{stats:{int:2,cha:1}}},{text:'The conversation is a distraction. Signal Kallen and the Black Knights for the external assault.',next:'cg_damocles_assault',effects:{stats:{cou:1,int:1}}}]};

CG_NODES['cg_schneizel_debate'] = {text:`Two princes. One fortress. Forty-seven warheads between them and a conversation that will decide the fate of billions.\n\nSchneizel pours tea. Earl Grey. Your mother's favorite — he knows this, and he wants you to know he knows.\n\n"Your United Federation is admirable," he says. "But fragile. It relies on trust between nations that have spent centuries betraying each other. One crisis — one food shortage, one border dispute, one ambitious general — and it fractures. My system does not fracture. Fear is more reliable than trust."\n\n"Your system requires a perfectly rational actor holding the trigger forever. What happens when you die?"\n\n"I have considered that. Damocles will be automated. An AI system that monitors global conflict indicators and deploys FLEIJA warheads based on predetermined thresholds. No human judgment. No human error."\n\nThe horror of it crystallizes. Not a dictator — a machine. A permanent, unkillable peace enforcer with no capacity for mercy, context, or change.\n\n"You would remove human choice from the equation entirely," you say.\n\n"Choice is the problem, Lelouch. Humans choose war. Humans choose cruelty. Remove the choice, and you remove the suffering."\n\n"You also remove the possibility of choosing kindness. Of choosing growth. Of choosing to be better than we were yesterday."\n\nSchneizel sips his tea. "Poetic. But poetry does not stop bombs."\n\nC.C. watches from the corner. She has lived centuries. She has seen this argument before — the eternal debate between freedom and safety, played out by two boys who happen to have the power to decide it for everyone.\n\n"You are both wrong," she says. They look at her. "And you are both right. That is why this is hard."\n\nThe chess clock ticks. Outside, the Black Knights' fleet approaches Damocles. Inside, two brothers play the final game.\n\nSchneizel places a piece on the board between them. A white king.\n\n"Checkmate in seven moves," he says. "Unless you have something I have not anticipated."`,scene:'confrontation',mood:'#2a0845',characters:['CC','Schneizel'],effects:{stats:{int:2,cha:1}},choices:[{text:'"I have Nunnally." Play the one card Schneizel cannot calculate — family.',next:'cg_damocles_nunnally',effects:{stats:{cha:2},relationships:{nunnally:2}}},{text:'Flip the board. Geass the automated system itself — command the machine to self-destruct.',next:'cg_damocles_climax',effects:{stats:{int:2,cou:1}}}]};

CG_NODES['cg_damocles_nunnally'] = {text:`Schneizel's mask cracks. Just for a moment — a fissure in the marble.\n\n"Nunnally is irrelevant to this equation."\n\n"Nunnally is the ENTIRE equation." You stand. "You built Damocles to save the world. But you forgot to ask the world if it wants to be saved this way. Nunnally asked. She spoke to delegates from forty nations. She asked them: 'Would you trade your freedom for guaranteed safety?' Do you know what they said?"\n\nSchneizel is quiet.\n\n"They said no. Every single one. Because safety without freedom is a cage, and humans would rather die free than live in chains — even golden ones. Even ones built by a genius. Even ones that actually work."\n\nYou pull out a device — a communicator linked to every head of state in the United Federation. Nunnally's voice fills the command center, transmitted live to the world.\n\n"My name is Nunnally vi Britannia. I am speaking to everyone aboard Damocles — the crew, the engineers, the soldiers who believe they are protecting the world. My brother Schneizel wants to save you from war. He is sincere. He is also wrong."\n\nHer voice is steady. Stronger than you have ever heard it.\n\n"Peace cannot be imposed. It must be chosen. Every day. By every person. It is harder than what Schneizel offers. It is messier, slower, and it will fail sometimes. But it is OURS. Our peace. Our choice. Our world."\n\n"I am asking you — not commanding, not threatening, asking — to lower your weapons. Come home. Choose the harder peace."\n\nThe command center goes silent. The crew looks at Schneizel. Schneizel looks at the window.\n\nOne by one, console operators stand and step away from their stations. A junior officer removes her headset. A weapons technician powers down his terminal.\n\nSchneizel watches his perfect system unravel — not from force, not from strategy, but from a blind girl in a wheelchair asking people to be brave.`,scene:'confrontation',mood:'#636e72',characters:['Schneizel','Nunnally','CC'],effects:{stats:{cha:2},relationships:{nunnally:3,schneizel:1}},choices:[{text:'Accept Schneizel\'s surrender. He lost — but he lost to hope, not force.',next:'cg_ending_damocles_falls',effects:{stats:{cha:2,per:1}}},{text:'Schneizel will not stop. Geass him now, while his guard is down.',next:'cg_damocles_climax',effects:{stats:{int:1,cou:1}}}]};

CG_NODES['cg_damocles_assault'] = {text:`The United Federation fleet moves on Damocles. Three hundred warships against one fortress — terrible odds, because the fortress has FLEIJA warheads and the fleet does not.\n\nKallen leads the vanguard in the Guren SEITEN. Tohdoh commands the main battle group. Cornelia — the Britannian princess turned reluctant ally — coordinates from the flagship, her tactical mind turning the chaos into something resembling a plan.\n\nThe first FLEIJA launches. A sphere of annihilation blooms in space — silent, beautiful, erasing thirty ships and six thousand lives in an instant. The fleet recoils.\n\n"He will fire again in four minutes," you broadcast to the fleet. "In that window, I need three squadrons to draw fire while Kallen's team breaches the lower hull."\n\n"Three squadrons as bait," Cornelia responds. "You are asking me to sacrifice—"\n\n"I am asking you to trust me. Four minutes. If Kallen does not breach, we retreat. But if she does—"\n\n"She will breach," Kallen's voice cuts in. Calm. Certain. The voice of someone who has already decided this fight is won. "Just keep that thing pointed away from me for four minutes."\n\nThe diversionary squadrons break formation. They scatter like startled birds, drawing Damocles' targeting systems in every direction. FLEIJA warheads are devastating but slow to aim — Schneizel designed them for cities, not dogfights.\n\nKallen dives. The Guren's radiant wave surger tears through Damocles' lower hull like a knife through tinfoil. Behind her, Suzaku — in the Lancelot, fighting alongside the Black Knights for the first time — widens the breach.\n\nTwo Knightmare Frames enter the fortress. The clock reads three minutes forty seconds.\n\nInside Damocles, the corridors are chaos. Security drones. Automated defenses. Schneizel's personal guard — elite soldiers who believe they are saving the world.\n\nKallen fights with the fury of someone who has lost too many friends to watch the world end in mathematical certainty. Suzaku fights with the precision of someone atoning for every wrong choice.\n\nYou coordinate from the command ship, watching the battle unfold on tactical screens, moving pieces on a board only you can see.\n\nTwo minutes.`,scene:'battle',mood:'#cc0000',characters:['Kallen','Cornelia','Suzaku'],effects:{stats:{cou:2,int:1}},choices:[{text:'Join the assault personally. Board Damocles and confront Schneizel face to face.',next:'cg_damocles_climax',effects:{stats:{cou:2}}},{text:'Stay on the command ship. The strategy matters more than the sword.',next:'cg_damocles_climax',effects:{stats:{int:2}}}]};

CG_NODES['cg_damocles_climax'] = {text:`The FLEIJA control room. The heart of Damocles. Banks of monitors showing warhead trajectories, target coordinates, yield calculations. The mathematics of extinction, displayed in clean white text on black screens.\n\nSchneizel stands at the center. Around him, his remaining loyalists — Kanon, his aide, and a dozen soldiers who chose certainty over freedom.\n\n"One warhead remains armed," Schneizel says. He is calm. He is always calm. "Targeted at Pendragon — the Britannian capital. Thirty million people."\n\nHe holds a detonator. Simple. Black. A button that ends a city.\n\n"If I press this, the world learns the lesson I intended: war has consequences. Absolute, irreversible consequences. And they will never risk it again."\n\n"You would murder thirty million people to prove a point."\n\n"I would sacrifice thirty million to save seven billion. The math is clear, Lelouch. You of all people understand sacrifice for the greater good."\n\nHe is right. You do understand. The Zero Requiem — your own plan — was built on the same logic. One death to save a world. Schneizel simply scales it up.\n\nThe difference is consent. You planned to sacrifice yourself. Schneizel plans to sacrifice others.\n\n"The math is clear," you agree. "But math does not bleed. People do."\n\nYou look at C.C. She nods — imperceptibly. She has been alive for centuries. She has seen empires rise and fall. She knows what comes next.\n\nYou activate your Geass. Not on Schneizel — his lens blocks it. On yourself.\n\nThe command you gave yourself months ago, buried so deep even you forgot: "When Schneizel holds the detonator, your body will move on its own. Take it from him. Whatever the cost."\n\nYour body moves. Faster than thought. Your hand closes on the detonator at the same moment Schneizel's thumb moves toward the button.\n\nA gunshot. Pain — white, absolute, in your shoulder. Kanon's pistol. But your hand does not release. Cannot release. Your own Geass holds you.\n\nThe detonator is yours. Schneizel stares at you — and for the first time in his life, the Second Prince of Britannia looks surprised.\n\n"You Geassed yourself," he whispers. "That is... actually brilliant."\n\n"I learned from the best manipulator I know," you reply, bleeding freely. "You."`,scene:'battle',mood:'#cc0000',characters:['CC','Schneizel'],effects:{stats:{cou:2,int:2}},choices:[{text:'Destroy the detonator. Disable every FLEIJA warhead. End Damocles forever.',next:'cg_ending_damocles_falls',effects:{stats:{int:1,cou:1}}},{text:'Use the detonator as leverage. Force Schneizel to dismantle Damocles on live broadcast.',next:'cg_ending_damocles_falls',effects:{stats:{cha:2,int:1}}}]};

CG_NODES['cg_ending_damocles_falls'] = {text:`Damocles falls.\n\nNot in fire — you ensured that. The FLEIJA warheads are disarmed one by one, their detonation cores extracted by engineering teams working around the clock. The fortress itself descends on emergency thrusters, guided to a controlled landing in the Pacific — far from any populated coastline.\n\nIt hits the water like a dying whale. The impact sends a tsunami that your meteorological teams anticipated and evacuated for. No casualties. No cities erased. Just a very expensive piece of technology becoming the world's largest artificial reef.\n\nSchneizel is taken into custody. Not by the Black Knights — by the United Federation's newly formed International Court. He will be tried. Fairly. Publicly. With lawyers and evidence and all the messy, imperfect machinery of justice that he tried to replace with mathematics.\n\nHe goes quietly. At the trial, he delivers a closing statement that makes half the gallery weep:\n\n"I was not wrong about the problem. War is humanity's oldest disease. But I was wrong about the cure. You cannot heal a patient by removing their will to live. I removed choice because I was afraid of what people would choose. My brother — my infuriating, theatrical, cape-wearing brother — was brave enough to trust them."\n\nHe looks at you from the defendant's box. The ghost of a smile.\n\n"For what it is worth, Lelouch — I am glad you won. The world deserves better than my version of peace."\n\nThe sentence is life imprisonment. A cell with books, chess problems, and a window overlooking the ocean where Damocles sank.\n\nYou visit him once. You play chess. He wins, because Schneizel always wins at chess.\n\n"The board is different now," he says, moving his queen. "No FLEIJA warheads. No floating fortresses. Just two brothers and sixty-four squares."\n\n"I prefer this version."\n\n"So do I." He captures your rook. "But I will still beat you."\n\nOutside, the world continues its messy, imperfect, stubbornly free existence. Nations argue. Diplomats bicker. Borders are drawn and redrawn. It is chaotic and frustrating and occasionally beautiful.\n\nC.C. eats pizza on the balcony of your apartment in the Tokyo Settlement — no longer a settlement, just Tokyo again.\n\n"You know," she says, "for a demon emperor who faked his death and came back from exile and destroyed a flying fortress, you are remarkably boring in person."\n\n"I prefer 'peacefully domestic.'"\n\n"I prefer 'boring.' Pass the pepperoni."`,scene:'end',mood:'#1a3a1a',ending:'The Fortress Falls',characters:['CC','Schneizel','Kallen','Suzaku','Nunnally'],choices:[]};

CG_NODES['cg_suzaku_knight_oath'] = {text:`The ceremony is held at the Kururugi shrine. Not Pendragon. Not the Tokyo Settlement. The place where two boys caught frogs and argued about whether bugs were cool.\n\nSuzaku kneels. Not before an emperor — before the United Federation's charter. The document lies on a simple wooden table, weighted by a stone from the shrine's garden.\n\n"I, Suzaku Kururugi, renounce my oath to the Holy Britannian Empire. I swear instead to protect the peace of the United Federation of Nations — not through conquest, not through the sword of a tyrant, but through service to every person who chooses to be free."\n\nHis voice breaks on "free." The word has cost him everything — his father, his honor, his identity as the White Knight. He rebuilt himself from the wreckage, and this is what emerged: not a weapon, but a guardian.\n\nYou stand beside him. Zero's mask is in your hands, but you do not wear it. Today you are just Lelouch — a friend witnessing another friend's rebirth.\n\nKallen watches from the second row. Her eyes are complicated — pride, grief, something she will not name. She and Suzaku fought on opposite sides for years. Now they stand on the same one, and the geometry of that shift is still settling.\n\n"The Lancelot has been decommissioned," Suzaku tells you afterward, drinking tea in the shrine's garden. "I asked them to melt it down. Use the Sakuradite for civilian energy production."\n\n"You loved that machine."\n\n"I loved what it let me do — protect people. But I was protecting the wrong things. The Empire. The system. My own guilt." He sets down his cup. "Euphemia told me once that the strongest knights protect without swords. I did not understand then. I do now."\n\nA frog croaks in the garden pond. Same pond. Same frogs. Different boys.\n\n"So what now?" you ask.\n\n"Now I do the boring part. Diplomatic security. Treaty enforcement. Making sure nobody builds another Damocles." He almost smiles. "You get the cape and the drama. I get the paperwork."\n\n"I retired the cape."\n\n"Lelouch, you will never retire the cape. It is who you are."`,scene:'emotional',mood:'#636e72',characters:['Suzaku','Kallen'],effects:{stats:{cha:1},relationships:{suzaku:3,kallen:1},flags:{suzaku_oath:true}},choices:[{text:'Help Suzaku build the Federation security apparatus. The new world needs new guardians.',next:'cg_ending_new_order',effects:{stats:{int:1},relationships:{suzaku:2}}},{text:'Let Suzaku walk his own path. He does not need you anymore.',next:'cg_ending_new_order',effects:{stats:{per:1},relationships:{suzaku:1}}}]};

CG_NODES['cg_ending_new_order'] = {text:`Five years after the fall of Damocles.\n\nThe world is not perfect. It was never going to be perfect. But it is better — measurably, stubbornly, imperfectly better.\n\nJapan is sovereign. The Chinese Federation is a democracy — messy, loud, argumentative, everything a democracy should be. The EU has stabilized. Africa is rebuilding. Britannia — what remains of it — has transformed into a constitutional monarchy with Nunnally as a figurehead queen who spends most of her time advocating for refugee rights.\n\nSuzaku runs Federation Security from a modest office in Geneva. No Knightmare Frame. No white cape. Just a desk, a coffee machine that barely works, and the quiet satisfaction of preventing wars that never make the news.\n\nKallen teaches political science at Tokyo University. Her students do not know she once piloted a machine that could level a city block. They know her as Professor Kozuki — intense, fair, with a tendency to use military metaphors that confuse the freshmen.\n\nCornelia commands the Britannian Self-Defense Force. She misses the old days sometimes — the clarity of battle, the simplicity of enemies and allies. But she watches Euphemia's portrait in her office and remembers why clarity was never the goal.\n\nOhgi is Prime Minister of Japan. Third term. He governs like he fought — stubbornly, honestly, with a complete inability to give a decent speech. The people love him for it.\n\nC.C. lives with you. She eats pizza. She watches the world with ancient eyes that have seen civilizations bloom and wither. Sometimes she tells you stories about the past — Geass users from centuries ago, empires that rose on borrowed power and fell when the bill came due.\n\n"You are the first one who paid it back," she says one evening. "The power. The debt. You used it and then put it down. Nobody does that."\n\n"I had help. A witch who eats too much pizza, a knight who caught frogs, a pilot who punches first and asks questions never."\n\n"And a sister who believed in you when you forgot how to believe in yourself."\n\n"And that."\n\nNunnally calls every Sunday. She is happy. Genuinely, uncomplicated happy — the kind of happiness you spent your entire adolescence fighting to give her.\n\nThe Geass is still there. Your eye still burns with the Sigil of Absolute Obedience. You have not used it in three years. You keep it as a reminder — of what you were willing to become, and what you chose instead.\n\nOn a shelf in your apartment, next to C.C.'s pizza coupons and a photo of two boys at a shrine, sits Zero's mask. Gathering dust. A relic of a person who was necessary once and is not anymore.\n\nThe sunset paints Tokyo in gold. C.C. steals the last slice of pizza. You do not stop her.\n\nThe game is over. The pieces are at rest. And the king — the real one, the one who learned that the strongest move is sometimes to stop playing — watches the world he helped build and thinks:\n\nThis is enough.\n\nIt was always enough.`,scene:'end',mood:'#1a3a1a',ending:'The New Order',characters:['CC','Suzaku','Kallen','Nunnally','Cornelia'],choices:[]};

CG_NODES['cg_federation_crisis'] = {text:`Three months after the liberation of the Chinese Federation, the cracks begin to show.\n\nEmpress Tianzi is fourteen. She is kind, brave, and completely unprepared to govern a nation of 1.4 billion people. Xingke — the only person she trusts — is dying. The tuberculosis is advanced. Britannian medical technology could extend his life by years, but the political cost of accepting enemy aid is enormous.\n\nThe provincial governors, freed from the Eunuchs' yoke, immediately begin fighting each other. Resources. Borders. Ethnic tensions that the old regime suppressed through brutality. Without the Eunuchs as a common enemy, the Federation threatens to Balkanize.\n\n"You freed them from tyranny," Diethard reports via secure channel. "Now they are free to tear each other apart. Congratulations."\n\nKallen is blunt: "We won the battle and lost the country."\n\nXingke, from his hospital bed, is calmer. "Chaos after liberation is natural. The question is whether we guide it toward something constructive or let it consume itself." He coughs blood into a handkerchief. "I have perhaps six months. Tianzi needs advisors who will outlast me."\n\nThe young Empress visits your temporary command post. She is small, pale, dressed in ceremonial robes too heavy for her frame. But her eyes are sharp.\n\n"Zero. My people are suffering. The governors steal from them the same way the Eunuchs did, but now they do it with patriotic speeches instead of silence." She straightens. "I am told I am too young to govern. I am told I am a figurehead. But Xingke believed in me. You freed me. Someone must believe I can do this."\n\nShe looks at you with the same terrified determination you have seen in every revolutionary who ever stood on a precipice.\n\n"Teach me," she says. "Teach me to be the Empress my people deserve."`,scene:'planning',mood:'#636e72',characters:['Kallen','CC'],effects:{stats:{int:1,cha:1},flags:{federation_crisis:true}},choices:[{text:'Stay in the Federation. Mentor Tianzi. Build institutions that will outlast any individual leader.',next:'cg_tianzi_mentorship',effects:{stats:{cha:2,int:1}}},{text:'Send advisors but return to Japan. The Federation must learn to stand on its own.',next:'cg_ending_new_order',effects:{stats:{per:1}}}]};

CG_NODES['cg_tianzi_mentorship'] = {text:`Teaching an Empress to govern is not like leading a rebellion. Rebellions are simple — you have an enemy, a cause, and a cape. Governance is spreadsheets. Governance is compromise. Governance is sitting in a room with twelve angry provincial governors and convincing them that sharing water rights is preferable to civil war.\n\nTianzi learns fast. Faster than you expected. She has Xingke's quiet intensity and something else — an emotional intelligence that you, with all your strategic brilliance, completely lack.\n\nShe reads people the way you read battlefields. In a negotiation with the southern provinces, she notices the governor of Yunnan fidgeting with his ring — a nervous habit. She pauses the meeting, asks about his family. His daughter is ill. Tianzi arranges medical treatment. The water rights agreement is signed the next day.\n\n"That was not strategy," you tell her afterward. "That was kindness."\n\n"Kindness IS strategy," she replies. "People follow threats because they must. They follow kindness because they choose to. Which leader lasts longer?"\n\nC.C. is impressed. "I have met a thousand rulers across five centuries. Most of them confused strength with cruelty. This child confuses kindness with strategy and somehow makes it work."\n\nXingke watches from his hospital bed, connected to machines that measure the remaining days he refuses to count. He smiles when he hears about Tianzi's negotiations. He smiles less when the coughing worsens.\n\n"Take care of her," he tells you one night, when the machines beep softly and the moonlight falls across his weakening frame. "Not the Empire. Not the Federation. HER. She is worth more than every nation I ever fought for."\n\nYou promise. It is the easiest promise you have ever made, because it is the one you were already keeping.`,scene:'emotional',mood:'#636e72',characters:['CC'],effects:{stats:{cha:2,int:1},relationships:{cc:1}},choices:[{text:'Formalize the mentorship. Help Tianzi establish a constitutional framework for the new Federation.',next:'cg_ending_new_order',effects:{stats:{int:2,cha:1}}},{text:'Focus on saving Xingke. His death would shatter Tianzi — and the Federation with her.',next:'cg_xingke_farewell',effects:{stats:{cha:1},relationships:{cc:1}}}]};

CG_NODES['cg_xingke_farewell'] = {text:`Xingke dies on a Tuesday. The machines stop beeping at 3:47 AM. The nurses say it was peaceful — that he simply stopped breathing, as if he had finished a task and decided to rest.\n\nYou do not believe it was peaceful. Nothing about Xingke's life was peaceful. He fought, bled, coughed blood into handkerchiefs and smiled through the pain because a fourteen-year-old Empress needed him to be strong. He spent his dying months teaching her everything he knew about war, diplomacy, and the burden of command — pouring himself into her future like water into a garden, knowing he would not see the flowers.\n\nTianzi does not cry at the funeral. Not in public. She stands before a million mourners in the Vermilion Forbidden City, wearing white robes of mourning, and delivers a eulogy that makes Schneizel's speechwriters look amateur:\n\n"Li Xingke gave his life for a country that tried to destroy him. He served an Empress who was too young to deserve his loyalty. He fought when fighting was hopeless and believed when belief was naive. He was the bravest person I have ever known, and I will spend the rest of my life trying to be worthy of what he gave me."\n\nShe pauses. Fourteen years old. Alone on a stage built for gods.\n\n"The Chinese Federation will not mourn General Xingke by stopping. We will mourn him by continuing. By building the nation he dreamed of — free, just, and brave enough to face tomorrow without him."\n\nThe crowd roars. A million voices. Xingke's name carries across the Forbidden City like a prayer.\n\nLater, in private, Tianzi collapses. The composure shatters. She cries into your shoulder — great, heaving sobs that shake her entire body. C.C. stands guard at the door, turning away mourners and ministers with the gentle authority of someone who has grieved more than any person should.\n\n"He promised he would stay," Tianzi whispers. "He promised."\n\n"He stayed as long as he could. Longer than he should have." You hold her — awkwardly, because you are not good at this, because Lelouch vi Britannia was built for chess and capes, not comfort. But you hold her anyway. "And he left you ready."\n\n"I am not ready."\n\n"Nobody ever is. You start anyway."`,scene:'emotional',mood:'#636e72',characters:['CC'],effects:{stats:{cha:2},relationships:{cc:2}},choices:[{text:'Stay with Tianzi through the transition. The Federation needs stability more than ever.',next:'cg_ending_new_order',effects:{stats:{cha:2,int:1}}},{text:'Return to Japan. Tianzi is stronger than she knows. Trust her.',next:'cg_ending_new_order',effects:{stats:{per:1}}}]};

CG_NODES['cg_kallen_aftermath'] = {text:`Kallen finds you on the rooftop of the old Ashford Academy. The school is closed now — repurposed as a community center after the liberation. But the rooftop is the same. The same view. The same sunset.\n\n"You come here a lot," she says. Not a question.\n\n"It is where I was normal. Before the Geass. Before Zero. I was just a student who played chess and pretended to care about homework." You lean against the railing. "I miss it sometimes."\n\n"You were never normal, Lelouch. You were a prince disguised as a student, plotting the destruction of an empire while eating lunch." She stands beside you. "I was a terrorist disguised as a schoolgirl, hiding a Knightmare Frame in a shipping container. Normal was never an option for either of us."\n\nThe sunset is doing its thing — painting the sky in oranges and purples, the kind of beauty that makes everything seem temporarily solvable.\n\n"Kallen. I need to say something I should have said before the war. Before Damocles. Before all of it."\n\n"If this is an apology, I do not want it. You already apologized. Fourteen times. I counted."\n\n"It is not an apology. It is a thank you." You turn to face her. "You followed a masked stranger into a war. You fought when the odds were insane. You stayed when everyone else left. And when I was exposed — when you learned Zero was a Britannian prince who had been lying to you since the first day — you punched me in the face and then came back to fight beside me anyway."\n\n"The punch was important. You deserved the punch."\n\n"I deserved the punch. But you did not have to come back. Nobody would have blamed you for walking away. You chose to stay. That choice saved the world as much as any strategy I ever designed."\n\nKallen is quiet for a long time. The sunset deepens. Tokyo — free Tokyo, sovereign Tokyo, Tokyo without the word 'Settlement' attached — glitters below.\n\n"I stayed because the cause was real," she says. "Even when the leader was fake, the cause was real. Japan deserved to be free. People deserved to choose their own lives. That was never a lie, even when everything else was."\n\nShe punches your shoulder. Gently. Well — gently for Kallen, which is still hard enough to leave a bruise.\n\n"Also, someone had to keep you alive. You have the survival instincts of a suicidal chess piece."`,scene:'emotional',mood:'#636e72',characters:['Kallen'],effects:{stats:{cha:1},relationships:{kallen:3}},choices:[{text:'"Stay. Not for the war. Not for Zero. Just... stay."',next:'cg_ending_new_order',effects:{stats:{cha:1},relationships:{kallen:3}}},{text:'"What will you do now? The war is over. You can be anyone."',next:'cg_ending_new_order',effects:{stats:{per:1},relationships:{kallen:2}}}]};


// ---- ARC: JEREMIAH GOTTWALD LOYALTY ----

CG_NODES['cg_jeremiah_orange'] = {text:`The aftermath of Zero's debut sends shockwaves through the Britannian military. But no one suffers more than Margrave Jeremiah Gottwald — the officer in command of the transport you intercepted, the man whose security you shattered on live television.\n\nJeremiah is a proud man. A knight of the old school — honor, duty, lineage. He served the late Empress Marianne, your mother, before her assassination. He does not know Zero's true identity. All he knows is that a masked terrorist humiliated him in front of the world.\n\nThe footage plays on every channel. During your escape, you used Geass on Jeremiah, forcing him to order his own troops to stand down. The media latches onto a single phrase from the chaos — "Orange" — a codeword you invented on the spot, meaningless, designed to make Britannian command think Jeremiah was a traitor.\n\nIt works too well.\n\n"Orange Boy," the tabloids call him. The Purist Faction — Jeremiah's ultranationalist clique within the military — strips him of rank. Fellow officers refuse to meet his eyes. His career, his honor, his entire identity as a loyal knight — destroyed by a word that means nothing.\n\nVilletta Nu, his former subordinate, delivers the news. "Command wants you reassigned. Effectively, you are finished, Jeremiah."\n\n"I am NOT finished," he snarls. "I will find Zero. I will tear that mask off. And I will prove — I will PROVE — that my loyalty to Britannia has never wavered."\n\nHe commandeers a Sutherland Knightmare and charges into the Shinjuku ghetto, alone, hunting you with the desperation of a man who has nothing left to lose.\n\nC.C. raises an eyebrow. "He is coming for you."\n\n"Let him come," you reply. "Jeremiah Gottwald is a relic — honor without strategy."\n\n"Relics can be dangerous," she says. "Especially when they have nothing left to protect but pride."`,scene:'confrontation',mood:'#d4a017',characters:['Jeremiah','CC'],effects:{stats:{per:1},flags:{jeremiah_disgraced:true}},choices:[{text:'Confront Jeremiah directly — use Geass to neutralize him permanently.',next:'cg_jeremiah_cyborg',effects:{stats:{int:1},flags:{jeremiah_geassed:true}}},{text:'Evade him and let his obsession consume him — a broken knight is no threat.',next:'cg_jeremiah_cyborg',effects:{stats:{per:1}}}]};
CG_NODES['cg_jeremiah_cyborg'] = {text:`Jeremiah Gottwald should be dead. After his failed assault on the Black Knights, he was left broken in the wreckage of his Knightmare — body shattered, career annihilated, name synonymous with treachery he never committed.\n\nBut the Britannian Empire does not waste useful hatred.\n\nCode R — the same research division that held C.C., the same project that birthed the Geass experiments — recovers Jeremiah's body. They rebuild him. Cybernetic enhancements fused with experimental anti-Geass technology. A Geass Canceller implanted in his left eye — a device that can nullify any Geass command.\n\nHe returns during the Black Knights' assault on the Britannian coastal base. A hulking figure, half-man half-machine, his orange eye blazing with mechanical fury.\n\n"ZERO!" His voice booms across the battlefield, amplified by speakers embedded in his rebuilt body. "I am Jeremiah Gottwald — Knight of the Empire, loyal servant of the Crown! You took my name! You took my honor! Today I take them BACK!"\n\nHis Siegfried — a massive, spherical Knightmare fortress — tears through your defensive lines. Kallen engages him in the Guren but the Siegfried is overwhelming, a rolling ball of destruction that shrugs off her radiant wave surger.\n\nWorse: the Geass Canceller. Anyone you have previously commanded snaps free of your orders. Guards you turned, officials you compromised — their Geass programming shatters like glass.\n\n"He is undoing everything," you whisper. "Every command I have ever given..."\n\nC.C. grips your shoulder. "Then you must face him as yourself. No Geass. No tricks. Just the truth."\n\n"What truth?"\n\n"That you are Marianne's son. He loved your mother, Lelouch. He became a knight because of her. If any truth can reach him through that armor, it is that one."`,scene:'battle',mood:'#cc0000',characters:['Jeremiah','Kallen','CC'],effects:{stats:{cou:1},flags:{geass_canceller:true}},choices:[{text:'Reveal your identity to Jeremiah — tell him you are Marianne vi Britannia\'s son.',next:'cg_jeremiah_loyalty',effects:{stats:{cha:2,cou:1},relationships:{jeremiah:3}}},{text:'Destroy the Siegfried by any means necessary — Jeremiah is too dangerous to reason with.',next:'cg_cornelia_battle',effects:{stats:{str:2},relationships:{jeremiah:-2}}}]};
CG_NODES['cg_jeremiah_loyalty'] = {text:`You open a private communication channel. No voice modulator. No mask filter. Just your real voice — the voice of a seventeen-year-old boy.\n\n"Jeremiah Gottwald. You served my mother. Marianne vi Britannia. You were her personal guard — and you have carried the guilt of her assassination every day since, because you were not there to protect her."\n\nThe Siegfried stops mid-charge. On the monitor, you see Jeremiah's face — the human half — contort with shock.\n\n"How... how do you know that?"\n\n"Because I am her son. Lelouch vi Britannia. The prince who was exiled. The prince who was supposed to die. I survived, Jeremiah. And I became Zero — not to destroy Britannia, but to find the truth about my mother's murder and build a world where my sister can live in peace."\n\nSilence on the channel. The Siegfried hovers, weapons armed, surrounded by Black Knight forces waiting for your order to fire.\n\nThen Jeremiah Gottwald — the Orange Knight, the disgraced margrave, the cybernetic weapon built to destroy you — does something no one expects.\n\nHe kneels.\n\nThe Siegfried's weapons power down. The massive frame descends to the ground and opens. Jeremiah steps out, tears streaming down the human side of his face.\n\n"My lady Marianne's son," he whispers. "All this time... I was fighting my lady's son."\n\n"Will you fight FOR her son instead?"\n\nJeremiah straightens. The military bearing returns — but now it serves a different purpose. "I, Jeremiah Gottwald, swear my eternal loyalty to Lelouch vi Britannia. I failed your mother. I will NOT fail you."\n\nKallen watches from the Guren, stunned. "Zero... did you just recruit the enemy's cyborg super-weapon by making him CRY?"\n\n"Loyalty is the most powerful weapon in the world, Kallen. Stronger than Knightmares. Stronger than Geass."\n\nJeremiah becomes your most devoted protector — the Geass Canceller now shielding you instead of hunting you. The Orange Knight reborn as the guardian of the prince he was always meant to serve.`,scene:'revelation',mood:'#d4a017',characters:['Jeremiah','Kallen'],effects:{stats:{cha:1},relationships:{jeremiah:5,kallen:1},flags:{jeremiah_loyal:true}},choices:[{text:'With Jeremiah\'s Geass Canceller, you have a counter to other Geass users. Hunt down the Geass Order.',next:'cg_vv_order',effects:{stats:{int:1,per:1}}},{text:'Use Jeremiah\'s knowledge of Britannian military operations to plan the next assault.',next:'cg_cornelia_battle',effects:{stats:{int:2}}},{text:'Jeremiah knows secrets about your mother\'s death — press him for answers.',next:'cg_schneizel_gambit',effects:{stats:{per:1},relationships:{jeremiah:1}}}]};


CG_NODES['cg_jeremiah_loyalty'] = {text:`You open a private communication channel. No voice modulator. No mask filter. Just your real voice — the voice of a seventeen-year-old boy.\n\n"Jeremiah Gottwald. You served my mother. Marianne vi Britannia. You were her personal guard — and you have carried the guilt of her assassination every day since, because you were not there to protect her."\n\nThe Siegfried stops mid-charge. On the monitor, you see Jeremiah's face — the human half — contort with shock.\n\n"How... how do you know that?"\n\n"Because I am her son. Lelouch vi Britannia. The prince who was exiled. The prince who was supposed to die. I survived, Jeremiah. And I became Zero — not to destroy Britannia, but to find the truth about my mother's murder and build a world where my sister can live in peace."\n\nSilence on the channel. The Siegfried hovers, weapons armed, surrounded by Black Knight forces waiting for your order to fire.\n\nThen Jeremiah Gottwald — the Orange Knight, the disgraced margrave, the cybernetic weapon built to destroy you — does something no one expects.\n\nHe kneels.\n\nThe Siegfried's weapons power down. The massive frame descends to the ground and opens. Jeremiah steps out, tears streaming down the human side of his face.\n\n"My lady Marianne's son," he whispers. "All this time... I was fighting my lady's son."\n\n"Will you fight FOR her son instead?"\n\nJeremiah straightens. The military bearing returns — but now it serves a different purpose. "I, Jeremiah Gottwald, swear my eternal loyalty to Lelouch vi Britannia. I failed your mother. I will NOT fail you."\n\nKallen watches from the Guren, stunned. "Zero... did you just recruit the enemy's cyborg super-weapon by making him CRY?"\n\n"Loyalty is the most powerful weapon in the world, Kallen. Stronger than Knightmares. Stronger than Geass."\n\nJeremiah becomes your most devoted protector — the Geass Canceller now shielding you instead of hunting you. The Orange Knight reborn as the guardian of the prince he was always meant to serve.`,scene:'revelation',mood:'#d4a017',characters:['Jeremiah','Kallen'],effects:{stats:{cha:1},relationships:{jeremiah:5,kallen:1},flags:{jeremiah_loyal:true}},choices:[{text:'With Jeremiah\'s Geass Canceller, you have a counter to other Geass users. Hunt down the Geass Order.',next:'cg_vv_order',effects:{stats:{int:1,per:1}}},{text:'Use Jeremiah\'s knowledge of Britannian military operations to plan the next assault.',next:'cg_cornelia_battle',effects:{stats:{int:2}}},{text:'Jeremiah knows secrets about your mother\'s death — press him for answers.',next:'cg_schneizel_gambit',effects:{stats:{per:1},relationships:{jeremiah:1}}}]};

// ---- ARC: MAO THE MIND READER ----

CG_NODES['cg_mao_appears'] = {text:`C.C. has been acting strange. Stranger than usual — which, for an immortal pizza-obsessed witch, is saying something.\n\nShe leaves for hours without explanation. Returns with scratches she did not have before. Looks over her shoulder in ways that suggest she is not watching for enemies — she is listening.\n\nThen the messages start. Notes left in your room at Ashford Academy — places C.C. could not have told anyone about. Notes written in a child's handwriting, filled with adult obsession.\n\n"I can hear you, C.C. I can hear everything. Come back to me."\n\n"I know about the boy. He is not worthy of our contract. I am."\n\n"If you will not come willingly, I will make him bring you."\n\nC.C. finally explains, and for the first time since you have known her, she looks afraid.\n\n"His name is Mao. He was... a previous contractor. I gave him Geass when he was six years old. His power is the ability to read minds — every thought, every memory, within a five-hundred-meter radius. He cannot turn it off."\n\n"Cannot?"\n\n"His Geass evolved beyond control years ago. He hears everyone, all the time. The only mind that gave him peace was mine — my Code protects me from Geass, so I was silence in his ocean of noise. I was supposed to stay with him, but..."\n\n"You abandoned him."\n\nHer silence is confirmation enough.\n\n"He has been tracking me for years," she says. "He is brilliant, unhinged, and he knows everything about everyone around him the moment they enter his range. Your strategies, your secrets, your identity — if he gets close enough, he will know ALL of it."\n\nYour blood runs cold. A mind reader. Every plan, every deception, every hidden truth you carry — an open book to this man. Geass cannot work on him if he sees the command coming. Your greatest weapon is useless against someone who reads your intent before you act.\n\n"He wants me back," C.C. says quietly. "And he will destroy everything you have built to get me."`,scene:'horror',mood:'#cc0000',characters:['CC'],effects:{stats:{per:1},relationships:{cc:2},flags:{mao_threat:true}},choices:[{text:'Set a trap for Mao — if he reads minds, use that against him. Think lies.',next:'cg_mao_confrontation',effects:{stats:{int:2}}},{text:'Let C.C. go to him — her past, her problem. You cannot risk the Black Knights.',next:'cg_mao_confrontation',effects:{stats:{int:1},relationships:{cc:-3}}}]};
CG_NODES['cg_mao_confrontation'] = {text:`Mao is waiting at Clovisland — an abandoned amusement park, its cheerful ruins a grotesque stage for the confrontation.\n\nHe is younger than you expected. White-haired, wild-eyed, wearing headphones blasting music at maximum volume — the only way he can muffle the constant torrent of thoughts pouring into his mind from every direction.\n\n"Lelouch vi Britannia!" Mao claps his hands, delighted. "Oh, you are FASCINATING. The things inside your head — the guilt, the rage, the beautiful hypocrisy. You use people like chess pieces and then cry about it in the dark. C.C. really knows how to pick them."\n\nHe pulls off his headphones. His eyes — both blazing with permanent Geass sigils — lock onto you.\n\n"I know everything. You are Zero. You killed Clovis. You have a blind sister you are obsessed with. You feel guilty about every soldier who dies following your orders but you do it anyway because the alternative is admitting you are wrong. And C.C. — MY C.C. — you think she cares about you? She is using you. She uses EVERYONE."\n\n"You are insane, Mao."\n\n"I am honest. There is a difference. I hear the truth that people hide. Do you know what truth sounds like, Lelouch? It sounds like SCREAMING. Every person is a ball of fear and selfishness wrapped in polite words. Except C.C. C.C. is silence. She is the only peace I have ever known, and you STOLE her."\n\nHe pulls out a chainsaw. Not a weapon of strategy — a weapon of madness.\n\n"I am going to take her back. And I am going to take you apart. Literally. I already know every move you are going to make before you make it."\n\nHe is right. Your hand drifts toward your eye — toward Geass — and he laughs. "I can see you planning to use it. I will close my eyes before the sigil activates. TRY AGAIN."\n\nThinking your way out of a fight with a mind reader requires the one thing Mao cannot read: what you are NOT thinking about.`,scene:'confrontation',mood:'#cc0000',characters:['Mao','CC'],effects:{stats:{int:1,cou:1}},choices:[{text:'Use recorded messages and pre-planned commands — think about nothing while a recording of your voice activates Geass.',next:'cg_mao_resolution',effects:{stats:{int:2,per:1}}},{text:'Overwhelm his mind — bring dozens of people into range, flood him with so many thoughts he cannot focus on yours.',next:'cg_mao_resolution',effects:{stats:{cha:1,int:1}}},{text:'Let C.C. handle it — this is between them. She gave him this curse.',next:'cg_mao_resolution',effects:{relationships:{cc:2}}}]};
CG_NODES['cg_mao_resolution'] = {text:`The confrontation ends in a parking garage beneath Clovisland, and it is not clean.\n\nMao is pinned — your strategy worked, barely. Whether through misdirection, sensory overload, or C.C.'s intervention, you created a gap in his mind-reading just long enough to act. But Mao is not defeated. He is sobbing.\n\n"C.C.! C.C., please! I did everything you asked! You said you would stay with me! You PROMISED!" He clutches the headphones around his neck like a talisman. "The voices never stop. They NEVER stop. You were the only quiet. Please... please be quiet again..."\n\nC.C. kneels beside him. For the first time, you see her face crack — not with the practiced detachment of an immortal, but with genuine pain. She did this. She gave a child the power to read minds and then left him alone when the power consumed him.\n\n"I am sorry, Mao," she says. "I should never have left you."\n\n"Then stay—"\n\n"I cannot. But I can give you peace."\n\nShe holds his face. Mao's eyes — wild, terrified, flooded with permanent Geass — slowly calm. Whatever she whispers to him, only he hears. His breathing steadies. His hands unclench.\n\nA shot rings out. Britannian police, tracking the disturbance, open fire. Mao crumples. C.C. catches him.\n\nThe boy who could hear every thought in the world finally finds silence.\n\nC.C. carries Mao's body to a rooftop and sits with him until dawn. You do not follow. Some grief is private, even from contractors.\n\nWhen she returns, her face is the mask again — ancient, unreadable, armored.\n\n"The Geass is a curse," she says. "Every user. Every time. Remember that, Lelouch. When the power feels like a gift, remember Mao."\n\nYou do remember. Every time your eye burns and the Geass hungers for activation, you see a white-haired boy screaming for silence in a world that would not stop talking.\n\nThe power of kings. The loneliness of gods.`,scene:'aftermath',mood:'#636e72',characters:['Mao','CC'],effects:{stats:{per:1},relationships:{cc:3},flags:{mao_defeated:true}},choices:[{text:'The encounter with Mao makes controlling your own Geass urgent. Train with C.C. before it is too late.',next:'cg_geass_control',effects:{stats:{per:2},relationships:{cc:1}}},{text:'Return to the war. Mao was a distraction — Britannia will not wait.',next:'cg_cornelia_battle',effects:{stats:{int:1,cou:1}}}]};

// ---- ARC: SHIRLEY FENETTE TRAGEDY ----

CG_NODES['cg_shirley_discovery'] = {text:`Shirley Fenette finds the gun in your room.\n\nShe was not snooping — she came to return a textbook, the door was unlocked, and the pistol was sitting on your desk next to a half-finished chess game and a black mask she has never seen before.\n\nShirley is everything you are not. Open, sincere, hopelessly optimistic. She has had a crush on you since freshman year — everyone at Ashford Academy knows it except, apparently, you. She tutors you in subjects you already know. She saves you seats in the cafeteria. She worries when you disappear for days.\n\nNow she is holding a gun and staring at a mask, and the careful architecture of your double life is crumbling.\n\nBut the gun is not the worst of it.\n\nHer father — Joseph Fenette — was killed at Narita. The landslide you triggered. The "acceptable losses" you dismissed. One of those losses was the father of the girl who loves you.\n\nShe does not know this yet. But she is investigating. Shirley Fenette — armed with nothing but a broken heart and a journalist's stubbornness — is tracing the connection between the Narita incident and the Black Knights. Between Zero and a Britannian student who disappears every time the masked revolutionary appears.\n\n"Lulu," she whispers to herself, turning the mask over in her hands. "What are you hiding?"\n\nMilly Ashford finds you in the hallway. "Shirley has been asking questions. About you. About where you go. She found something in your room — she would not tell me what."\n\nYour stomach drops. Shirley is not an enemy. She is not a threat. She is a civilian — an innocent — standing at the edge of a truth that will destroy her.\n\nIf she discovers you are Zero, she discovers you killed her father.\n\nIf she tells anyone, the Black Knights, the rebellion, everything collapses.\n\nAnd if you use Geass on her... you will have to live with commanding the girl who loves you to forget that love.`,scene:'daily',mood:'#636e72',characters:['Shirley','Milly'],effects:{stats:{per:1},relationships:{shirley:1},flags:{shirley_suspicious:true}},choices:[{text:'Talk to Shirley — not as Zero, but as Lelouch. Confess enough to satisfy her without revealing everything.',next:'cg_shirley_truth',effects:{stats:{cha:1},relationships:{shirley:2}}},{text:'Use Geass on Shirley — erase her memories of what she found. It is the only safe option.',next:'cg_shirley_geass',effects:{stats:{int:1},relationships:{shirley:-2},flags:{shirley_geassed:true}}}]};
CG_NODES['cg_shirley_truth'] = {text:`You find Shirley on the school rooftop — their spot, the place students go when the world is too heavy for hallways. She is crying. The mask is in her bag. The gun is in a trash can three floors down — she threw it away because holding it terrified her.\n\n"Lulu." She does not turn around. "My father died at Narita. The Black Knights triggered the landslide. Zero gave the order."\n\n"Shirley—"\n\n"I found the mask. I found the gun. I have been watching you for weeks — you disappear every time Zero appears. You come back with bruises you cannot explain. You know things about the military that a student should not know." She finally faces you. Her eyes are red, swollen, devastated. "Tell me I am wrong. Please. Tell me you are not Zero."\n\nThe silence stretches. You could lie. You are good at lying — the best. You have lied to armies, to nations, to people who followed you to their deaths.\n\nBut this is Shirley. And she deserves at least one truth.\n\n"I am Zero," you say.\n\nShe does not scream. She does not run. She just... breaks. Quietly, completely, like a window giving way to pressure it was never designed to hold.\n\n"You killed my father."\n\n"I did not know he was there. It does not matter — he is dead because of me. I am sorry, Shirley. That word is pathetically insufficient, but it is true."\n\n"Then why? WHY are you doing this?"\n\n"For my sister. For Japan. For a world that does not crush people under its boot because they were born on the wrong side of a border."\n\n"And my father? Was he on the wrong side?"\n\nYou have no answer. She knows it.\n\nShirley wipes her eyes. She reaches into her bag, pulls out the mask, and holds it out to you.\n\n"I hate you," she says. "And I love you. And I do not know which one is worse." She pushes the mask into your chest. "I will not tell anyone. Not because I believe in your cause. Because I am stupid enough to still believe in you."\n\nShe walks away. You stand on the rooftop holding the mask of Zero, and for the first time since the Geass, you feel truly monstrous — not because of what you have done, but because of who you have hurt.`,scene:'daily',mood:'#636e72',characters:['Shirley'],effects:{stats:{cha:1},relationships:{shirley:3},flags:{shirley_knows:true}},choices:[{text:'Shirley\'s knowledge makes her a target. Protect her — assign Jeremiah or a trusted Knight to watch over her.',next:'cg_cornelia_battle',effects:{relationships:{shirley:1}}},{text:'Shirley\'s grief is a mirror. Confront the cost of the landslide — the civilian deaths you dismissed.',next:'cg_euphemia',effects:{stats:{per:1},relationships:{ohgi:1}}}]};
CG_NODES['cg_shirley_geass'] = {text:`You find her at the school fountain, clutching the mask. She looks up — hopeful, terrified, desperately wanting you to have an explanation that makes it all okay.\n\n"Lulu, please tell me this is not what I think—"\n\n"Shirley." You activate the Geass. The red sigil blazes in your eye. Her pupils dilate, ringed with crimson. "Forget. Forget Zero. Forget the mask. Forget what you found in my room. Forget that your father died because of the Black Knights. Forget everything about this."\n\nHer face goes slack. The mask slips from her fingers. When the Geass releases her, she blinks — confused, disoriented, a girl standing by a fountain with no memory of why she came.\n\n"Oh — Lulu! Hi! Were we... meeting for something? I feel like I forgot something." She laughs, embarrassed. Normal. Happy.\n\nThe mask lies at your feet. You pocket it before she looks down.\n\n"Just running into each other," you say. "Want to get lunch?"\n\n"Sure!" She beams. The girl who loved you, who grieved her father, who discovered the truth — erased. Reset. A person you have edited because the unedited version was inconvenient.\n\nYou eat lunch together. She talks about a concert she wants to attend. You nod and smile and hate yourself with a precision that surprises you.\n\nC.C. finds you that evening. "You used Geass on that girl."\n\n"I had to."\n\n"No. You chose to. There is always another option. You chose the easy one." She pauses. "Mao's Geass read minds against his will. Yours commands obedience against theirs. Both of you reshape other people to suit your needs. The only difference is that Mao knew he was a monster."\n\nThe words land like a blade.\n\nMonths later, Shirley starts having fragments — dreams of a mask, a rooftop, a conversation that feels too real to be imagination. The Geass erased the memory, but it did not erase the feelings. She still loves you without knowing why. She still grieves her father without remembering the cause.\n\nShe is a ghost of herself — a half-person living on memories someone stole.\n\nAnd you are the thief.`,scene:'aftermath',mood:'#2a0845',characters:['Shirley','CC'],effects:{stats:{int:1},relationships:{shirley:-3,cc:-1},flags:{shirley_memory_erased:true}},choices:[{text:'The guilt is unbearable. When the war is over, you will find a way to restore her memories. You swear it.',next:'cg_cornelia_battle',effects:{stats:{per:1},relationships:{shirley:1}}},{text:'Compartmentalize. Shirley is safe because she does not remember. That must be enough.',next:'cg_cornelia_battle',effects:{stats:{int:1}}}]};

// ---- ARC: ASHFORD ACADEMY DOUBLE LIFE ----

CG_NODES['cg_ashford_life'] = {text:`The absurdity of your existence is this: by day, you are a high school student worried about attendance records.\n\nAshford Academy is a private school for Britannian elites — manicured lawns, marble columns, a student council with a budget larger than most resistance cells. The Ashford family shelters you and Nunnally in exchange for old loyalties to your mother. Here, you are not Zero. You are Lelouch Lamperouge, a slightly lazy honors student with a gambling habit and a gift for chess.\n\nMilly Ashford — student council president, granddaughter of the school's founder — runs the campus like a benevolent dictator with a fetish for absurd events. Today's atrocity: the Giant Pizza Festival.\n\n"We are building the world's largest pizza!" Milly announces, standing on a table, a blueprint unfurled behind her that looks like war plans for a calzone the size of a Knightmare Frame. "Twelve meters in diameter! Ashford Academy will hold the record!"\n\nRivalz groans. "Milly, where are we getting that much cheese?"\n\n"I have a sponsor." She winks at C.C., who is lurking in the corner in a school uniform she definitely should not be wearing, eyes glazed with pizza lust.\n\nYour phone buzzes. Ohgi: "Cornelia's forces are mobilizing near Saitama. We need orders."\n\nYou are elbow-deep in pizza dough. Kallen — who attends Ashford under her Britannian identity as a sickly rich girl — catches your eye across the room. Her expression says: "Are you seriously making pizza right now?"\n\nYes. Yes you are.\n\nBecause this — the dough, the laughter, Nunnally clapping flour-covered hands, Shirley arguing with Rivalz about toppings — this is what you are fighting for. Not territory. Not power. Normalcy. A world where your sister can bake a terrible pizza and smile.\n\nYou text Ohgi back under the table: "Deploy Tohdoh to Saitama perimeter. Defensive formation Gamma-7. I will coordinate in two hours."\n\nMilly slaps your phone out of your hand. "No texting during Pizza Fest! Student Council rules!"\n\n"Milly, I—"\n\n"PIZZA. FEST."\n\nYou sigh. The revolution can wait for cheese.`,scene:'daily',mood:'#d4a017',characters:['Milly','CC','Kallen','Nunnally'],effects:{stats:{cha:1},relationships:{nunnally:2,kallen:1}},choices:[{text:'Slip away during the festival to coordinate the Black Knights — duty calls.',next:'cg_contact_resistance',effects:{stats:{int:1},relationships:{nunnally:-1}}},{text:'Stay for the whole festival. Nunnally is happy. That matters more than one battle.',next:'cg_ashford_graduation',effects:{stats:{cha:1},relationships:{nunnally:2,kallen:1}}}]};
CG_NODES['cg_ashford_graduation'] = {text:`Senior year arrives with the quiet cruelty of calendars. Milly Ashford is graduating.\n\nThe Student Council organizes one final event — Milly's Farewell Festival. It is, predictably, unhinged. A school-wide treasure hunt where the "treasure" is Milly's hand in marriage — a joke, mostly, but several students take it alarmingly seriously.\n\nArthur the cat — the Student Council's unofficial mascot, a feral beast that bites Suzaku specifically and exclusively — is dressed in a tiny tuxedo and designated as the "ring bearer." He escapes immediately and climbs the clock tower.\n\nYou find yourself chasing a cat up a bell tower while simultaneously fielding encrypted communications from three Black Knight cells, and you wonder if this is what going insane feels like.\n\nKallen corners you on the third-floor landing. "Lelouch. Ohgi says Britannian reconnaissance drones have been spotted over our supply depot in Yokosuka."\n\n"Tell him to activate the decoy depot and reroute supplies through tunnel C-4."\n\n"You are giving military orders while chasing a cat."\n\n"I am an excellent multitasker."\n\nBelow, Milly gives her farewell speech. She does not know about Zero. She does not know about the Geass, or the Black Knights, or the war that is about to swallow her school whole. She talks about friendship and courage and the future — simple words that hit you like bullets because you know the future she is imagining does not exist.\n\n"I want everyone in this room to promise me something," Milly says, and her voice cracks — Milly, who never cracks. "Promise me you will be honest. With each other. With yourselves. Life is too short for masks."\n\nKallen looks at you. You look at the floor.\n\nAfter the ceremony, Nunnally holds your hand. "Milly was wonderful, was she not, big brother?"\n\n"She was."\n\n"Do you think... we will all be together next year? The Student Council?"\n\nYou squeeze her hand. "I will do everything I can to make sure of it."\n\nIt is the most honest lie you have ever told.`,scene:'daily',mood:'#636e72',characters:['Milly','Kallen','Nunnally'],effects:{stats:{cha:1},relationships:{nunnally:2,kallen:1},flags:{milly_graduated:true}},choices:[{text:'The festival is over. Back to war — Cornelia is planning something.',next:'cg_cornelia_battle',effects:{stats:{int:1}}},{text:'Kallen lingers after the festival. For the first time, she does not ask about Zero — she asks about you.',next:'cg_ashford_double',effects:{stats:{cha:1},relationships:{kallen:2}}}]};
CG_NODES['cg_ashford_double'] = {text:`The rooftop. After hours. Kallen sits on the railing with the casual disregard for gravity that comes from piloting a Knightmare Frame at three hundred kilometers per hour.\n\n"Who are you?" she asks. Not accusatory. Curious. "At school, you are this lazy, chess-obsessed rich kid who sleeps through history class. Then you put on the mask and you are Zero — this terrifying genius who moves armies like game pieces. Which one is real?"\n\n"Both. Neither." You sit beside her, close enough that the artificial distance between commander and soldier dissolves. "Lelouch is who I was before the world broke. Zero is who I became to fix it. Somewhere in between is... whatever I actually am."\n\n"That is a very pretty non-answer."\n\n"I am very good at those."\n\nShe laughs. You realize you have almost never heard Kallen laugh — not the polite giggle of her Britannian cover identity, but a real laugh. She is always fighting. Always angry. Always the soldier.\n\n"I am the same," she admits. "At school, I am this sickly Britannian girl who can barely climb stairs. In the Guren, I am the Black Knights' ace. Neither version is complete. The Britannian girl has no fight in her. The pilot has no softness." She looks at you sideways. "Maybe that is why I understand you. We are both half-people pretending to be whole."\n\nThe Tokyo settlement glitters below — Britannian luxury built on Japanese bones. Somewhere down there, Ohgi is coordinating supply runs. Tohdoh is drilling soldiers. C.C. is eating pizza and being cryptic.\n\nUp here, for five minutes, you are just two teenagers sitting on a roof.\n\n"When the war is over," Kallen says quietly. "Will you still exist? Without the mask, without the rebellion — will there be a Lelouch left?"\n\n"I do not know."\n\n"That scares you."\n\n"Terrifies me."\n\nShe puts her hand over yours. Brief. Warm. Then she stands, and the soldier returns.\n\n"Good talk, Zero. Now — about those reconnaissance drones over Yokosuka."`,scene:'daily',mood:'#636e72',characters:['Kallen'],effects:{stats:{cha:1},relationships:{kallen:3}},choices:[{text:'The quiet moment ends. War resumes — plan the response to Cornelia\'s movements.',next:'cg_cornelia_battle',effects:{stats:{int:1}}},{text:'Kallen deserves to know everything. Tell her about the Geass.',next:'cg_euphemia',effects:{stats:{cou:1},relationships:{kallen:2}}},{text:'Schneizel moves his pieces. The chess game that decides the world\'s fate awaits.',next:'cg_schneizel_chess',effects:{stats:{int:2}}}]};

// ---- ARC: V.V. AND THE GEASS ORDER ----

CG_NODES['cg_vv_order'] = {text:`The trail leads to a place that should not exist.\n\nBuried beneath a mountain in the Chinese Federation's western territories, hidden by a century of deliberate erasure from every map and database, lies the Geass Directorate — a facility the size of a small city, dedicated to one purpose: the mass production of Geass users.\n\nThe intelligence came from Jeremiah's memories, fragments of Cornelia's classified files, and C.C.'s reluctant admissions. The Directorate is run by a boy who appears no older than ten — blonde, cherubic, with an ancient cruelty in his eyes.\n\nV.V. Your uncle. Charles zi Britannia's twin brother. An immortal Code Bearer like C.C., but where C.C. is weary and withdrawn, V.V. is active, manipulative, and absolutely devoted to your father's plan.\n\n"V.V. and Charles made a contract decades ago," C.C. explains as your strike team approaches the facility. "They swore to create a world without lies — a world where every human thought is transparent. The Sword of Akasha."\n\n"The Sword of Akasha?"\n\n"A weapon that targets the collective unconscious — the shared psychic substrate of all humanity. If activated, it would merge every human mind into one. No secrets. No deception. No individuality."\n\nThe implications are staggering. Your father — the Emperor who conquered half the world — was not driven by ambition or greed. He was driven by an insane philosophy: destroy the concept of lying by destroying the concept of self.\n\n"That is why he needs Geass users," you realize. "The Directorate is not an army — it is a power source. Every Geass user feeds energy into the Thought Elevators, and the Thought Elevators power the Sword."\n\n"Yes. And V.V. has been recruiting for decades. Children, mostly. The younger the mind, the easier the Geass takes root." C.C.'s voice is flat, mechanical. "I helped build the system. Before I understood what it would become."\n\nThe facility's entrance looms — a steel door carved with the Geass sigil, pulsing faintly with red light.`,scene:'revelation',mood:'#2a0845',characters:['CC','Jeremiah'],effects:{stats:{int:1,per:1},flags:{geass_order_found:true}},choices:[{text:'Assault the Directorate — shut down the Geass production and confront V.V. directly.',next:'cg_vv_confrontation',effects:{stats:{cou:2,str:1}}},{text:'Infiltrate quietly — learn everything about the Sword of Akasha before V.V. knows you are here.',next:'cg_vv_confrontation',effects:{stats:{int:2,per:1}}},{text:'Father. Emperor. The man who abandoned you and Nunnally. It is time to face Charles in the World of C.',next:'cg_charles_confrontation',effects:{stats:{cou:2}}}]};
CG_NODES['cg_vv_confrontation'] = {text:`The Geass Directorate is a horror.\n\nRows upon rows of capsules — children suspended in fluid, Geass sigils flickering in their closed eyes. Monitors display brain activity: neural pathways reshaped, personalities overwritten, human beings reduced to batteries for a weapon they will never understand.\n\n"They volunteered," V.V. says, appearing from the shadows with the casual grace of a predator in its den. He looks like a child — golden hair, cherub's face, school uniform. He has looked this way for over sixty years.\n\n"They were children. Children cannot volunteer for this."\n\n"Children are the only ones honest enough to want power without pretending they deserve it." V.V. tilts his head — a gesture so eerily similar to C.C.'s that you realize they must have known each other for centuries. "Hello, nephew. I was wondering when you would find this place."\n\n"You killed my mother."\n\nV.V.'s smile freezes. There it is — the truth you have been chasing since the Geass first activated. Marianne vi Britannia was not killed by terrorists or political rivals. She was killed by V.V. — her husband's twin brother — because Marianne's own Geass ability threatened V.V.'s exclusive bond with Charles.\n\n"She was in the way," V.V. says, and for a moment the child's mask slips and something ancient and jealous peers through. "Charles and I made a promise. A world without lies. Marianne wanted to change the plan — soften it, compromise it. I could not allow that."\n\n"So you murdered a mother in front of her daughter. Nunnally watched. She was blinded by the trauma and crippled by the bullets your assassin put in her legs."\n\n"Collateral damage."\n\nThe words hit you like Geass itself — absolute, irrevocable, enraging. This child-shaped immortal crippled your sister and orphaned you because of a PHILOSOPHY.\n\nV.V. raises his hand. The children in the capsules stir — their Geass abilities activating in concert, a psychic wave that hammers against your mind. V.V.'s own Code flares, and the Directorate itself seems to come alive — defense systems, Knightmare drones, and dozens of Geass-controlled soldiers between you and the truth.\n\n"You cannot kill me, Lelouch. I am immortal. And this facility is my domain."\n\nJeremiah steps forward, his Geass Canceller blazing. "Then let me cancel your domain, Your Highness."`,scene:'confrontation',mood:'#cc0000',characters:['VV','Jeremiah','CC'],effects:{stats:{cou:1},relationships:{jeremiah:2},flags:{vv_confronted:true}},choices:[{text:'Fight through the Directorate — Jeremiah\'s Canceller can neutralize the Geass soldiers. Reach V.V. and end this.',next:'cg_sword_of_akasha',effects:{stats:{str:2,cou:1}}},{text:'Hack the Directorate\'s systems — free the children from their capsules, turning V.V.\'s weapon into a liability.',next:'cg_sword_of_akasha',effects:{stats:{int:2,per:1}}},{text:'Nunnally discovers that her brother is Zero.',next:'cg_nunnally_truth'}]};

// ============================================================
// SCENARIO DATA — MOB PSYCHO 100: EMOTIONAL EXPLOSION
// ============================================================
CG_NODES['cg_euphemia_massacre'] = {text:`The Special Administrative Zone of Japan. Euphemia's dream — a place where Elevens and Britannians could live as equals, without war, without resistance, without Zero. She stood on that stage with the purest intentions you have ever witnessed in a person born into empire, and she meant every word. Peace. Reconciliation. A future built on something other than blood.\n\nYou were there to support it. Or perhaps to test it. Or perhaps because some part of you — the part that remembers Nunnally's smile and the days before everything became strategy and sacrifice — wanted to believe it could work.\n\nThen the Geass activated.\n\nYou did not mean to. You were making a joke — a dark, hypothetical joke about the worst possible command — and the Geass, which had been growing stronger, which you had been told would eventually slip beyond your control, chose that precise moment to evolve. The red sigil blazed in both eyes. The command left your lips before conscious thought could intercept it.\n\n"Kill all the Japanese."\n\nEuphemia's eyes went blank. Then they filled with something that was not her — a mechanical obedience wearing her face, her voice, her hands. She turned to the crowd with a smile that looked like hers but was not, and she gave the order.\n\nThe massacre begins. Britannian soldiers, following their princess's command, open fire on the Japanese civilians who came in peace, who came because Euphemia asked them to, who came because they believed.\n\nYou stand frozen for three seconds. Three seconds in which the architecture of your entire rebellion, your identity as Zero, your relationship with your sister, your capacity for believing you are the hero of this story — all of it restructures around a single catastrophic truth: you did this. Not Britannia. Not Charles. You. A careless word and an uncontrolled power and the girl who wanted peace is now the instrument of genocide.\n\nThe three seconds end. You become Zero again. Because Zero is the only thing left that can function in this moment, and someone has to stop what you started.\n\nYou give the order to the Black Knights: stop Euphemia. By any means necessary. The resistance you built to fight tyranny is now fighting the consequences of your own mistake, and the bitter irony of it tastes like copper in your mouth.\n\nSuzaku will never forgive you. Euphemia — the real Euphemia, trapped somewhere behind the Geass command, watching her body do things she would die rather than choose — she deserved so much better than this. Than you.\n\nThe Special Administrative Zone burns. Your Geass burns. And somewhere inside you, the last piece of the person you were before this moment burns too.`,scene:'tragedy',mood:'#8b0000',characters:['Euphemia','Suzaku','Zero'],effects:{stats:{int:1,wis:1},flags:{saz_massacre:true,geass_out_of_control:true,euphemia_lost:true}},choices:[{text:'Use this tragedy. Reframe the massacre as Britannia showing its true face — become the symbol the rebellion needs.',next:'cg_create_zero',effects:{stats:{cha:2,int:1},flags:{massacre_exploited:true}}},{text:'Find Suzaku. Face what you have done. He deserves the truth, even if it destroys you.',next:'cg_suzaku_showdown',effects:{stats:{cou:3,emp:1},relationships:{suzaku:-3}}},{text:'Seek C.C. The Geass is out of control. You need answers before it takes more from you.',next:'cg_vv_confrontation',effects:{stats:{int:2},relationships:{cc:2},flags:{geass_control_sought:true}}}]};
CG_NODES['cg_charles_confrontation'] = {text:`The World of C exists outside time. You know this because time, here, has the consistency of water — it flows around you rather than through you, and the memories of the dead drift like luminous fish in a sea without shores.\n\nEmperor Charles zi Britannia stands at the center of it all. Your father. The man who abandoned you and Nunnally to a war zone, who built an empire on inequality and contempt, who has been orchestrating something far larger than conquest.\n\nThe Sword of Akasha hangs above you both — the weapon designed to kill God. Not metaphorically. Charles means to use the collective unconscious of humanity, channeled through the Thought Elevator system, to destroy the concept of lies itself. A world without deception. A world where every thought is transparent, every intention visible, every mask stripped away.\n\n"Ragnarok," Charles says. His voice carries the weight of a man who has spent decades building toward this single moment. "The death of the old world and the birth of something honest. No more masks, Lelouch. No more lies. No more Zero."\n\nMarianne is here too. Your mother. Alive — or rather, preserved in a form that transcends the distinction between alive and dead, her consciousness stored in this space by Charles's design. She smiles at you with warmth that feels genuine and that therefore cuts deeper than any blade.\n\nThey want you to join them. Your parents, reunited in a dimension beyond death, offering you a world without falsehood. It sounds beautiful. It sounds like everything a child abandoned by his parents might dream of.\n\nBut you are not that child anymore. You are Zero. And you understand, with a clarity that burns, what a world without lies actually means: a world without privacy, without growth, without the merciful distance that allows people to change. A world frozen in absolute truth is a world that cannot evolve, because evolution requires the gap between what we are and what we pretend to be — the lie that we could be better, which sometimes, impossibly, makes us so.\n\n"I reject you," you say to the God of this world. "I reject a world that cannot change." The Geass blazes. And for the first time, you use the power of absolute command not on a person, but on a concept.`,scene:'confrontation',mood:'#2d0a4e',characters:['Charles','Marianne','God'],effects:{stats:{cou:3,int:2,wis:2},flags:{ragnarok_confronted:true,parents_faced:true}},choices:[{text:'Command God to cease existing. Destroy the Ragnarok Connection and free humanity to keep its beautiful, terrible lies.',next:'cg_nunnally_truth',effects:{stats:{cou:3},flags:{god_killed:true}}},{text:'Hesitate. Your mother is here. The family you lost is offering you everything. Can you really destroy that?',next:'cg_shirley_truth',effects:{stats:{emp:2},relationships:{marianne:1}}},{text:'Turn to C.C. She has been alive for centuries. She knows what a world without lies would truly become.',next:'cg_vv_confrontation',effects:{stats:{int:2},relationships:{cc:3}}}]};
CG_NODES['cg_schneizel_chess'] = {text:`The chess board between you has always been metaphorical. Today it is literal — and the metaphor has teeth.\n\nSchneizel el Britannia. Second prince. The man who never needed Geass because his mind was weapon enough. He plays chess the way he wages war: with perfect logic, zero emotional investment, and the serene confidence of someone who has never lost because he has never cared enough about the outcome for losing to matter.\n\nYou have beaten everyone else. Cornelia fell to strategy. Charles fell to philosophy. The Black Knights fell to revelation. But Schneizel operates in a space beyond ideology — he is pure function, pure optimization, and his current optimization target is the total subjugation of the world through FLEIJA, the weapon that erases cities from existence.\n\nHe sits across from you in the Damocles — his floating fortress, armed with enough FLEIJA warheads to level every population center on Earth. His expression is pleasant. It is always pleasant. That is what makes him terrifying.\n\n"You and I are the same, Lelouch," he says, moving a knight. "We both see people as pieces. The difference is that I am honest about it."\n\n"The difference," you reply, moving your bishop, "is that I am willing to sacrifice the king."\n\nHe pauses. For Schneizel, a pause is the equivalent of another person screaming. He studies the board. He studies you. He is looking for the angle — the hidden variable, the piece you have positioned three moves ago that he has not yet identified.\n\nYou let him look. Because the piece he cannot find is not on the board. The piece he cannot find is the fact that you have already decided to lose everything — your reputation, your freedom, your life — in service of a plan so audacious that even Schneizel's perfect logic cannot model it, because it requires a variable his calculations exclude: genuine self-sacrifice.\n\nThe game continues. Each move is a conversation. Each capture is an argument. And somewhere in the gap between his perfect logic and your desperate conviction, the future of the world is being decided by two brothers who learned to fight at the same board, in the same palace, under the same absent father.\n\nCheckmate is coming. The question is whose.`,scene:'confrontation',mood:'#1a1a2e',characters:['Schneizel','Lelouch'],effects:{stats:{int:3,cou:2},flags:{schneizel_confrontation:true,damocles_battle:true}},choices:[{text:'Spring the trap. Geass Schneizel now — one command, absolute obedience, the war ends.',next:'cg_nunnally_truth',effects:{stats:{int:2},flags:{schneizel_geassed:true}}},{text:'Keep playing. Schneizel will reveal his weakness through his moves — patience is the weapon.',next:'cg_ashford_double',effects:{stats:{int:3,wis:1}}},{text:'Abandon the game. Storm the FLEIJA controls directly. Strategy is finished — this is survival.',next:'cg_suzaku_showdown',effects:{stats:{cou:3,str:1},flags:{damocles_assault:true}}}]};
CG_NODES['cg_zero_requiem_prep'] = {text:`The plan has a name now. You gave it one because plans without names are just intentions, and intentions are not enough for what you are about to do.\n\nZero Requiem.\n\nYou sit in the Imperial Palace — Emperor Lelouch vi Britannia, conqueror of the world, tyrant by design. The throne room is empty except for C.C., who sits on the steps with her knees drawn up, eating pizza from a box that has no business being in an imperial chamber but has appeared there anyway because C.C. exists in a permanent state of doing exactly what she wants.\n\n"You are sure," she says. Not a question. She knows you are sure. She has watched you build this plan from the ruins of everything you destroyed to get here.\n\nThe plan is simple. Elegant. Horrifying.\n\nStep one: become the most hated person in the world. You have done this. You conquered Britannia, then conquered every other nation, then made yourself a tyrant so absolute that the entire planet unites in hatred against you. Every crime, every atrocity, every act of cruelty — calculated, performed, absorbed into the narrative of Lelouch the Monster.\n\nStep two: concentrate all the world's hatred onto a single point. You. Only you. Every grievance, every injustice, every reason to fight — all of it aimed at one person sitting on one throne.\n\nStep three: die.\n\nPublicly. Dramatically. At the hands of Zero — the masked symbol of justice you created years ago, now worn by Suzaku Kururugi, the man who has every reason to kill you and who will do it not from hatred but from understanding.\n\nWhen Emperor Lelouch dies, the world's hatred dies with him. The sins of Britannia, the legacy of Charles, the wars and the suffering and the inequality — all of it buried with the tyrant. And from the ashes, a world united not by conquest but by shared relief. Peace born from the collective exhale of a civilization that watched its greatest monster fall.\n\nThe cost is everything. Your name will be a curse. Nunnally will grieve. The people you fought for will celebrate your death. History will remember you as the worst emperor who ever lived.\n\nC.C. watches you process this for the thousandth time. "You could still walk away," she offers, and the gentleness in her voice — from a woman who has lived centuries and watched countless contractors die — nearly breaks you.\n\n"No," you say. "I really cannot."\n\nShe nods. She knew. She has always known.\n\nTomorrow, you will parade through the streets as a conqueror. Suzaku, dressed as Zero, will descend from the sky. The blade will find its mark. The world will cheer.\n\nTonight, you sit with the only person who knows the truth, and you do not pretend the silence is comfortable.`,scene:'calm',mood:'#2d1b4e',characters:['CC','Suzaku','Nunnally'],effects:{stats:{cou:3,wis:3,emp:2},flags:{zero_requiem_planned:true,final_sacrifice_accepted:true}},choices:[{text:'Go through with it. The Zero Requiem is the only path to lasting peace.',next:'cg_nunnally_truth',effects:{stats:{cou:3},flags:{zero_requiem_committed:true}}},{text:'Seek Nunnally one last time. She does not know the plan. She deserves a moment, even if not the truth.',next:'cg_shirley_truth',effects:{stats:{emp:3},relationships:{nunnally:3}}},{text:'Talk to C.C. about her wish. She kept her end of the contract. You owe her that.',next:'cg_vv_confrontation',effects:{stats:{emp:2},relationships:{cc:5},flags:{cc_wish_addressed:true}}}]};

CG_NODES['cg_nunnally_truth'] = {text:`The silence in the room is the loudest thing you have ever heard.

Nunnally sits very still in her chair, hands folded in her lap, the familiar composure she has cultivated through years of helplessness and hope arranged perfectly on her face. But it is cracking. You can see it cracking the way ice cracks before it gives — from the inside out, with that specific dryness that comes just before everything becomes water.

"Say it again," she says. Her voice is steady. That is the worst part. "Say it where I can hear it properly."

You are Zero. You have been Zero. You built the Black Knights on the architecture of her name — told yourself, told the world, told the cold executive part of your mind that orchestrates catastrophes the way other people arrange furniture, that everything was for her. The wheelchair. The blindness. The small circumference of a life that empire had pressed her into. You burned half a continent trying to widen it.

"I am Lelouch," you say. "I was always Lelouch."

She opens her eyes.

It is not metaphor — or rather it is metaphor, but it is also simply true. The blindness she has carried since childhood, since the bomb, since the precise moment the world your father built collapsed inward on both of you, was never fully darkness. The Geass pressed into her in those final frantic moments granted her the ability to read the memories embedded in touch, and now, reaching out and taking your hand, she sees everything. Not selected highlights. Everything.

Shinjuku. The massacre order. The Knights of Rounds you outmaneuvered and the people you sacrificed in the outmaneuvering. The geass commands you issued to people who trusted you. Euphemia's name — the accident that was also a choice that was also a catastrophe that you have not once allowed yourself to grieve properly because grief requires stillness and stillness has never been something you could afford.

And underneath all of it, threaded through every calculation and every sacrifice and every performance: her face. Her name in your chest like a splinter you had decided to call a compass. Every atrocity rationalized through the image of a world she could live in freely.

She is crying. She has not moved her hand from yours.

"You destroyed everything," she says. It is not an accusation. It is a statement of geography — a map of what exists now versus what existed before. She is not wrong. The order you built the Zero Requiem to protect has been unmade at the root. The world is rewriting itself in the space you blasted open with your death.

"Yes," you say.

"For me."

"Yes. And — " you stop. Even now, the honesty costs something. "And because I wanted to. Because it was the one problem I believed I could solve. I am sorry, Nunnally. I am not certain that is a thing that can be adequately said."

She pulls your hand to her face. She is shaking. You realize, with a precision that bypasses all your defenses, that you are too.

"I would have chosen differently," she tells you. "If you had asked me. I would have chosen you alive over any of it."

The world you gave her is better than the one you were born into. You both know it. You both know what it cost. The gap between those two facts is the size of a brother, and it will never close.`,scene:'confrontation',mood:'#5a1a6b',characters:['Lelouch','Nunnally'],effects:{stats:{wis:2,cou:1}},choices:[{text:'Tell her the full truth of the Zero Requiem — make sure she understands why the death had to be yours.',next:'cg_zero_requiem'},{text:'Ask her what she would have the world be now — let her voice be the one that shapes what comes next.',next:'cg_end_zero_requiem'},{text:'Say nothing more. Sit with her in the silence of everything that cannot be undone.',next:'cg_end_emperor'},{text:'The plan crystallizes. Zero Requiem — the ultimate sacrifice. Begin the preparations.',next:'cg_zero_requiem_prep',effects:{stats:{cou:2,wis:1}}}]};
window.SCEN_NODES['cg'] = CG_NODES;
})();
